table = null;
planes = [];
pruebas = [];
modificado = false;
funcionalidades_predefinidos = [];
plan_creditos_seleccionado = null;
planes_antecedentes = [];
plan_antecedentes_seleccionado = null;

$(document).ready(function() {
    $(document).on('input', '#precio_plan_visual, #precio_creditos_visual, #precio_antecedentes_visual', function() {
        actualizarValorDesdeInput();
    });
});

/**
 * Establecer el tipo de prueba en el selector del formulario.
 * @param {number} tipo_prueba_id ID del tipo de prueba.
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Daniel Beltrán
 * @author Andres Morales
 * @author Jair Carvajal
 */
function seleccionarTipoPrueba(tipo_prueba_id) {
    $('#contenedor-plan').empty();
    $('#contenedor-plan').append(`
        <div class="card-body text-center">
            <button type="button" id="elegir-plan" class="btn btn-outline-primary" disabled onclick="modalElegirPlan();">Elegir plan</button>
        </div>
    `);
    $('#seccion-pruebas').addClass('d-none');
    $('#plan_id').val('');
    pruebas = [];
    // Convertir tipo_prueba_id a array si no lo es
    let tipos_prueba = Array.isArray(tipo_prueba_id) ? tipo_prueba_id : [tipo_prueba_id];
    // Crear los botones según los tipos de prueba seleccionados
    let botones_html = '<div class="card-body text-center">';
    tipos_prueba.forEach(function(tipo_id) {
        let texto_boton = 'Elegir plan';
        let clase_boton = 'btn-outline-primary';
        if (tipo_id == 1) {
            texto_boton = 'Elegir Plan de Selección';
            clase_boton = 'btn-outline-primary';
        } else if (tipo_id == 2) {
            texto_boton = 'Elegir Plan de Créditos IA';
            clase_boton = 'btn-outline-info';
        } else if (tipo_id == 3) {
            texto_boton = 'Elegir Plan de Antecedentes';
            clase_boton = 'btn-outline-success';
        }
        botones_html += `
            <button type="button" id="elegir-plan-${tipo_id}" class="btn ${clase_boton} mx-1 my-1" disabled onclick="modalElegirPlan(${tipo_id});">
                ${texto_boton}
            </button>
        `;
    });
    botones_html += '</div>';
    $('#contenedor-plan').append(botones_html);
    $('#tipo_prueba_id').val(tipo_prueba_id).trigger('select2');
    if (tipo_prueba_id && (Array.isArray(tipo_prueba_id) ? tipo_prueba_id.length > 0 : tipo_prueba_id)) {
        // Habilitar todos los botones creados
        tipos_prueba.forEach(function(tipo_id) {
            $(`#elegir-plan-${tipo_id}`).prop('disabled', false);
        });
        $.ajax({
            type: 'GET',
            url : `/pruebas-listado`,
            data: {
                tipo_prueba_id: tipo_prueba_id,
                activo: 1
            }
        }).then((respuesta) => {
            limpiarAdicional();
            $('#contenedor-pruebas').empty();
            pruebas = respuesta.data;
            for (let i = 0; i < pruebas.length; i++) {
                $('#contenedor-pruebas').append(`
                    <div class="col-12 col-md-6">
                        <div class="d-flex align-items-center">
                            <div class="check-container my-1 me-1">
                                <input type="checkbox" id="prueba-${pruebas[i].id}" name="prueba-${pruebas[i].id}" value="${pruebas[i].id}" class="form-check-input input-dinamico pruebas" onchange="ValidarPruebas();">
                            </div>
                            <label class="text-label-1" for="prueba-${pruebas[i].id}">${pruebas[i].nombre}</label>
                        </div>
                    </div>
                `);
            }
            if (opcion == 'facturar' || opcion == 'editar') {
                for (let i = 0; i < pruebas_empresa_plan.length; i++) {
                    $(`#prueba-${pruebas_empresa_plan[i].id}`).prop('checked', true);
                }
                $('#seccion-pruebas').removeClass('d-none');
                mostrarPlanSeleccionado();
            }
            if (opcion == 'editar') {
                $('#tipo_prueba_id').prop('disabled', true);
            }
        }).catch((error) => {
            console.error(error);
        });
    } else {
        $('#elegir-plan').prop('disabled', true);
    }
}
/**
 * Establecer el tipo de prueba en el selector del formulario.
 * @param {number} tipo_prueba_id ID del tipo de prueba.
 * @returns {void}
 * @author Jair Carvajal
 */
function seleccionarTipoPruebaMultiple() {
    let tipos_prueba = $('#tipo_prueba_id').val() || [];
    tipos_prueba = tipos_prueba.filter(function(tipo_id) {
        return tipo_id !== null && tipo_id !== '' && tipo_id !== undefined;
    });
    if (tipos_prueba.length === 0) {
        // Si no hay tipos seleccionados, limpiar todo
        $('#contenedor-plan').empty();
        $('#contenedor-creditos').empty();
        $('#seccion-pruebas').addClass('d-none');
        $('#plan_id').val('');
        $('#plan_id').prop('required', false);
        $('#plan_id').prop('disabled', true);
        $('#plan_credito_id').val('');
        $('#creditos').val('');
        plan_seleccionado = null;
        plan_creditos_seleccionado = null;
        pruebas = [];
        return;
    }
    let tiene_seleccion = tipos_prueba.includes('1') || tipos_prueba.includes(1);
    let tiene_creditos = tipos_prueba.includes('2') || tipos_prueba.includes(2);
    let tiene_antecedentes = tipos_prueba.includes('3') || tipos_prueba.includes(3);
    $('#plan_id').prop('required', tiene_seleccion);
    $('#plan_id').prop('disabled', !tiene_seleccion);
    // Manejo del plan de selección
    if (tiene_seleccion) {
        // Si hay un plan seleccionado, mantenerlo; si no, mostrar el botón
        if (plan_seleccionado === null && $('#contenedor-plan').children().length === 0) {
            let seccion_seleccion = `
                <p class="text-headline-4 text-gray-10 mb-2">Plan de Selección</p>
                <div class="card rounded rounded-3">
                    <div class="card-body text-center">
                        <button type="button" id="elegir-plan-1" class="btn btn-outline-primary mx-1 my-1" onclick="modalElegirPlan(1);">
                            Elegir Plan de Selección
                        </button>
                    </div>
                </div>
            `;
            $('#contenedor-plan').html(seccion_seleccion);
        }
    } else {
        // Si se deseleccionó el tipo de selección, limpiar el plan
        $('#contenedor-plan').empty();
        plan_seleccionado = null;
        $('#plan_id').val('');
    }
    // Manejo del plan de créditos
    if (tiene_creditos) {
        // Si hay un plan de créditos seleccionado, mantenerlo; si no, mostrar el botón
        if (plan_creditos_seleccionado === null && $('#contenedor-plan-creditos').length === 0) {
            let seccion_creditos = `
                <div class="mt-3" id="contenedor-plan-creditos">
                    <p class="text-headline-4 text-gray-10 mb-2">Plan de Créditos IA</p>
                    <div class="card rounded rounded-3">
                        <div class="card-body text-center">
                            <button type="button" id="elegir-plan-2" class="btn btn-outline-primary mx-1 my-1" onclick="modalElegirPlan(2);">
                                Elegir Plan de Créditos IA
                            </button>
                        </div>
                    </div>
                </div>
            `;
            $('#contenedor-creditos').html(seccion_creditos);
        }
    } else {
        // Si se deseleccionó el tipo de créditos, limpiar el plan de créditos
        $('#contenedor-creditos').empty();
        $('#contenedor-plan-creditos').remove();
        plan_creditos_seleccionado = null;
        $('#plan_credito_id').val('');
        $('#creditos').val('');
    }
    // Manejo del plan de antecedentes
    if (tiene_antecedentes) {
        if (plan_antecedentes_seleccionado === null && $('#contenedor-antecedentes').children().length === 0) {
            let seccion_antecedentes = `
                <div class="mt-3" id="contenedor-plan-antecedentes-inner">
                    <p class="text-headline-4 text-gray-10 mb-2">Plan de Antecedentes</p>
                    <div class="card rounded rounded-3">
                        <div class="card-body text-center">
                            <button type="button" id="elegir-plan-3" class="btn btn-outline-success mx-1 my-1" onclick="modalElegirPlan(3);">
                                Elegir Plan de Antecedentes
                            </button>
                        </div>
                    </div>
                </div>
            `;
            $('#contenedor-antecedentes').html(seccion_antecedentes);
        }
    } else {
        $('#contenedor-antecedentes').empty();
        plan_antecedentes_seleccionado = null;
        $('#plan_antecedente_id').val('');
        $('#consultas_antecedentes').val('');
        $('#contenedor-precio-antecedentes').addClass('d-none');
    }
    $.ajax({
        type: 'GET',
        url : `/pruebas-listado`,
        data: {
            tipo_prueba_id: tipos_prueba,
            activo: 1
        }
    }).then((respuesta) => {
        limpiarAdicional();
        $('#contenedor-pruebas').empty();
        pruebas = respuesta.data;
        for (let i = 0; i < pruebas.length; i++) {
            $('#contenedor-pruebas').append(`
                <div class="col-12 col-md-6">
                    <div class="d-flex align-items-center">
                        <div class="check-container my-1 me-1">
                            <input type="checkbox" id="prueba-${pruebas[i].id}" name="prueba-${pruebas[i].id}" value="${pruebas[i].id}" class="form-check-input input-dinamico pruebas" onchange="ValidarPruebas();">
                        </div>
                        <label class="text-label-1" for="prueba-${pruebas[i].id}">${pruebas[i].nombre}</label>
                    </div>
                </div>
            `);
        }
        if (opcion == 'facturar' || opcion == 'editar') {
            for (let i = 0; i < pruebas_empresa_plan.length; i++) {
                $(`#prueba-${pruebas_empresa_plan[i].id}`).prop('checked', true);
            }
            $('#seccion-pruebas').removeClass('d-none');
            mostrarPlanSeleccionado();
        }
        if (opcion == 'editar') {
            $('#tipo_prueba_id').prop('disabled', true);
        }
    }).catch((error) => {
        mostrarToast('danger', 'Ocurrió un error al intentar abrir la factura');
    });
}
/**
 * Obtener el listado de planes según el tipo_prueba_id seleccionado anteriormente.
 * @param {number|null} tipo_especifico ID del tipo de prueba específico (opcional).
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Jair Carvajal
 */
function modalElegirPlan(tipo_especifico = null) {
    let tipo_prueba_para_consulta = tipo_especifico !== null ? tipo_especifico : $('#tipo_prueba_id').val();
    // Si es tipo 2 (Créditos IA), cargar planes de créditos
    if (tipo_prueba_para_consulta == 2 || tipo_prueba_para_consulta == '2') {
        $.ajax({
            type: 'GET',
            url: '/planes-creditos',
            data: {
                activo: true
            }
        }).then((respuesta) => {
            planes_creditos = respuesta.data.planes;
            mostrarPlanesCreditos();
        }).catch((error) => {
            mostrarToast('danger', 'Ocurrió un error');
        });
        return;
    }

    // TODO: Reemplazar data quemada
    if (tipo_prueba_para_consulta == 3 || tipo_prueba_para_consulta == '3') {
        planes_antecedentes = [
            { id: 1, nombre: 'Plan Básico Antecedentes', precio: 150000, consultas: 10, empresas_activas: 3 },
            { id: 2, nombre: 'Plan Estándar Antecedentes', precio: 350000, consultas: 30, empresas_activas: 7 },
            { id: 3, nombre: 'Plan Premium Antecedentes', precio: 800000, consultas: 100, empresas_activas: 12 },
        ];
        mostrarPlanesAntecedentes();
        return;
    }

    $.ajax({
        type: 'GET',
        url : `/planes-listado`,
        data: {
            tipo_prueba_id: $('#tipo_prueba_id').val()
        }
    }).then((respuesta) => {
        planes = respuesta.data;
        mostrarPlanes();
    }).catch((error) => {
        console.error(error);
    });
}
/**
 * Mostrar los planes de créditos en el modal.
 * @returns {void}
 * @author Jair Carvajal
 */
function mostrarPlanesCreditos() {
    let filtro_orden = $('#filtro-plan-credito').val();
    let buscar = $('#buscador-plan-credito').val() || '';
    // Ordenar planes según el filtro
    let planes_ordenados = [...planes_creditos];
    if (filtro_orden === 'Mayor') {
        planes_ordenados.sort((a, b) => b.creditos - a.creditos);
    } else if (filtro_orden === 'Menor') {
        planes_ordenados.sort((a, b) => a.creditos - b.creditos);
    }
    if (buscar !== '') {
        planes_ordenados = planes_ordenados.filter(plan =>
            plan.nombre.toLowerCase().includes(buscar.toLowerCase())
        );
    }
    $('#contenedor-planes-creditos').empty();
    if (planes_ordenados.length === 0) {
        $('#contenedor-planes-creditos').append(`
            <div class="text-center py-5">
                <p class="text-muted">No se encontraron planes</p>
            </div>
        `);
    }
    for (let i = 0; i < planes_ordenados.length; i++) {
        let plan = planes_ordenados[i];
        let creditos_disponibles = plan.creditos_disponibles || plan.creditos || 0;
        let creditos_promedio = plan.creditos_promedio_accion || 0;
        let acciones_estimadas = creditos_disponibles > 0 && creditos_promedio > 0
            ? Math.floor(creditos_disponibles / creditos_promedio)
            : 0;
        $('#contenedor-planes-creditos').append(`
            <div class="card rounded rounded-3 border-hover pointer mb-3" onclick="elegirPlanCreditos(${i}, ${filtro_orden === 'Mayor' ? 'true' : 'false'});">
                <div class="row align-items-center m-0 w-100 px-3 py-4">
                    <div class="col">
                        <div class="text-headline-6 text-gray-10">${plan.nombre}</div>
                    </div>
                    <div class="col-auto">
                        ${crearTag({
                            texto: 'Créditos disponibles: ' + plan.creditos.toLocaleString('es-CO'),
                            class: 'tag-tonal-yellow',
                        })}
                    </div>
                    <div class="col-auto text-primary fw-bold">
                        ${crearTag({
                            texto: 'Acciones estimadas: ' + acciones_estimadas.toLocaleString('es-CO'),
                            class: 'tag-tonal-yellow',
                        })}
                    </div>
                </div>
            </div>
        `);
    }
    if (typeof $.fn.modal !== 'undefined') {
        $('#modal-planes-creditos').modal('show');
    }
    $('#buscador-plan-credito').off('input').on('input', function() {
        mostrarPlanesCreditos();
    });
}
/**
 * Elegir un plan de créditos IA.
 * @param {number} indice Índice del plan en el array.
 * @param {boolean} orden_mayor Si está ordenado de mayor a menor.
 * @returns {void}
 * @author Jair Carvajal
 */
function elegirPlanCreditos(indice, orden_mayor = false) {
    // Aplicar el mismo ordenamiento que en mostrarPlanesCreditos
    let planes_ordenados = [...planes_creditos];
    if (orden_mayor) {
        planes_ordenados.sort((a, b) => b.creditos - a.creditos);
    } else {
        planes_ordenados.sort((a, b) => a.creditos - b.creditos);
    }
    plan_creditos_seleccionado = planes_ordenados[indice];
    // Establecer los valores en los campos hidden
    $('#plan_credito_id').val(plan_creditos_seleccionado.id);
    $('#creditos').val(plan_creditos_seleccionado.creditos);
    mostrarPlanCreditosSeleccionado();
    if (typeof $.fn.modal !== 'undefined') {
        $('#modal-planes-creditos').modal('hide');
    }
}
/**
 * Mostrar el plan de créditos seleccionado en el contenedor.
 * @returns {void}
 * @author Jair Carvajal
 * @author Andres Gonzalez
 */
function mostrarPlanCreditosSeleccionado() {
    if (!plan_creditos_seleccionado || !plan_creditos_seleccionado.creditos) {
        mostrarToast('danger', 'Ocurrió un error'+plan_creditos_seleccionado);
        return;
    }
    let creditos_disponibles = plan_creditos_seleccionado.creditos_disponibles || plan_creditos_seleccionado.creditos || 0;
    let creditos_promedio = plan_creditos_seleccionado.creditos_promedio_accion || 0;
    let acciones_estimadas = creditos_disponibles > 0 && creditos_promedio > 0
        ? Math.floor(creditos_disponibles / creditos_promedio)
        : 0;
    let seccion_creditos = `
        <div class="mt-3" id="contenedor-plan-creditos">
            <p class="text-headline-4 text-gray-10 mb-2">Plan de Créditos IA</p>
            <div class="card rounded rounded-3">
                <div class="row align-items-center m-0 w-100 px-3 py-4 pointer" onclick="modalElegirPlan(2);">
                    <div class="col">
                        <div class="text-headline-6">${plan_creditos_seleccionado.nombre || 'Plan de Créditos'}</div>
                    </div>
                    <div class="col-auto">
                        ${crearTag({
                            texto: 'Créditos disponibles: ' + plan_creditos_seleccionado.creditos.toLocaleString('es-CO'),
                            class: 'tag-tonal-yellow',
                        })}
                    </div>
                    <div class="col-auto text-primary fw-bold">
                        ${crearTag({
                            texto: 'Acciones estimadas: ' + acciones_estimadas.toLocaleString('es-CO'),
                            class: 'tag-tonal-yellow',
                        })}
                    </div>
                </div>
            </div>
        </div>
    `;
    // Remover el contenedor anterior si existe
    $('#contenedor-plan-creditos').remove();
    // Agregar después del contenedor-plan o dentro de contenedor-creditos
    if ($('#contenedor-creditos').length) {
        $('#contenedor-creditos').html(seccion_creditos);
    } else {
        $('#contenedor-plan').after(seccion_creditos);
    }
    // Mostrar campos de precio para plan de créditos
    $('#contenedor-precio-creditos').removeClass('d-none');
    if (plan_creditos_seleccionado && plan_creditos_seleccionado.precio) {
        let precio_creditos = parseInt(plan_creditos_seleccionado.precio);
        $('#precio_creditos_original').val(precio_creditos);
        $('#precio_creditos_visual').val(precio_creditos).trigger('input');
        $('#precio_creditos_visual').prop('disabled', false);
        $('#porcentaje_descuento_creditos').val('');
    }
    actualizarValorVentaTotal();
}

/**
 * Mostrar los planes de antecedentes en el modal.
 *
 * @returns {void}
 * @author Jair Carvajal
 */
function mostrarPlanesAntecedentes() {
    let filtro_orden = $('#filtro-plan-antecedente').val() || 'Mayor';
    let buscar = $('#buscador-plan-antecedente').val() || '';
    let planes_ordenados = [...planes_antecedentes];
    if (filtro_orden === 'Mayor') {
        planes_ordenados.sort((a, b) => b.consultas - a.consultas);
    } else if (filtro_orden === 'Menor') {
        planes_ordenados.sort((a, b) => a.consultas - b.consultas);
    }
    if (buscar !== '') {
        planes_ordenados = planes_ordenados.filter(plan =>
            plan.nombre.toLowerCase().includes(buscar.toLowerCase())
        );
    }
    $('#contenedor-planes-antecedentes').empty();
    if (planes_ordenados.length === 0) {
        $('#contenedor-planes-antecedentes').append(`
            <div class="text-center py-5">
                <p class="text-muted">No se encontraron planes</p>
            </div>
        `);
    }
    for (let i = 0; i < planes_ordenados.length; i++) {
        let plan = planes_ordenados[i];
        $('#contenedor-planes-antecedentes').append(`
            <div class="card rounded rounded-3 border-hover pointer mb-3" onclick="elegirPlanAntecedentes(${i}, ${filtro_orden === 'Mayor' ? 'true' : 'false'});">
                <div class="row align-items-center m-0 w-100 px-3 py-4">
                    <div class="col">
                        <div class="text-headline-6 text-gray-10">${plan.nombre}</div>
                    </div>
                    <div class="col-auto">
                        ${crearTag({
                            texto: 'Consultas incluidas: ' + plan.consultas.toLocaleString('es-CO'),
                            class: 'bg-scale-yellow-90',
                        })}
                    </div>
                    <div class="col-auto text-primary fw-bold">
                        ${crearTag({
                            texto: '$ ' + plan.precio.toLocaleString('es-CO'),
                            class: 'bg-scale-yellow-90',
                        })}
                    </div>
                </div>
            </div>
        `);
    }
    if (typeof $.fn.modal !== 'undefined') {
        $('#modal-planes-antecedentes').modal('show');
    }
    $('#buscador-plan-antecedente').off('input').on('input', function() {
        mostrarPlanesAntecedentes();
    });
}

/**
 * Elegir un plan de antecedentes.
 *
 * @param {number} indice Índice del plan en el array.
 * @param {boolean} orden_mayor Si está ordenado de mayor a menor.
 * @returns {void}
 * @author Jair Carvajal
 */
function elegirPlanAntecedentes(indice, orden_mayor = false) {
    let planes_ordenados = [...planes_antecedentes];
    if (orden_mayor) {
        planes_ordenados.sort((a, b) => b.consultas - a.consultas);
    } else {
        planes_ordenados.sort((a, b) => a.consultas - b.consultas);
    }
    plan_antecedentes_seleccionado = planes_ordenados[indice];
    $('#plan_antecedente_id').val(plan_antecedentes_seleccionado.id);
    $('#consultas_antecedentes').val(plan_antecedentes_seleccionado.consultas);
    mostrarPlanAntecedentesSeleccionado();
    if (typeof $.fn.modal !== 'undefined') {
        $('#modal-planes-antecedentes').modal('hide');
    }
}

/**
 * Mostrar el plan de antecedentes seleccionado en el contenedor.
 *
 * @returns {void}
 * @author Jair Carvajal
 */
function mostrarPlanAntecedentesSeleccionado() {
    if (!plan_antecedentes_seleccionado || !plan_antecedentes_seleccionado.consultas) {
        mostrarToast('danger', 'Ocurrió un error al seleccionar el plan de antecedentes');
        return;
    }
    let seccion_antecedentes = `
        <div class="mt-3" id="contenedor-plan-antecedentes-inner">
            <p class="text-headline-4 text-gray-10 mb-2">Plan de Antecedentes</p>
            <div class="card rounded rounded-3">
                <div class="row align-items-center m-0 w-100 px-3 py-4 pointer" onclick="modalElegirPlan(3);">
                    <div class="col">
                        <div class="text-headline-6">${plan_antecedentes_seleccionado.nombre || 'Plan de Antecedentes'}</div>
                    </div>

                    <div class="col-auto">
                        ${crearTag({
                            texto: 'Consultas asignadas: ' + plan_antecedentes_seleccionado.consultas.toLocaleString('es-CO'),
                            class: 'bg-scale-yellow-90',
                        })}
                    </div>
                    <div class="col-auto text-primary fw-bold">
                        ${crearTag({
                            texto: 'Costo base: ' + plan_antecedentes_seleccionado.precio.toLocaleString('es-CO'),
                            class: 'bg-scale-yellow-90',
                        })}
