/**
 * Actualizar el valor de venta total sumando plan de selección y créditos.
 * 
 * @returns {void}
 * @author Andres Gonzalez
 * @author Jair Carvajal
 */
function actualizarValorVentaTotal() {
    let valor_plan = 0;
    let valor_creditos = 0;
    let valor_antecedentes = 0;

    if (plan_seleccionado && plan_seleccionado.precio) {
        valor_plan = parseFloat(plan_seleccionado.precio) || 0;
    }

    if (plan_creditos_seleccionado && plan_creditos_seleccionado.precio) {
        valor_creditos = parseFloat(plan_creditos_seleccionado.precio) || 0;
    }

    if (plan_antecedentes_seleccionado && plan_antecedentes_seleccionado.precio) {
        valor_antecedentes = parseFloat(plan_antecedentes_seleccionado.precio) || 0;
    }

    let valor_total = valor_plan + valor_creditos + valor_antecedentes;

    // Formatear el valor con separador de miles
    let valor_formateado = valor_total.toLocaleString('es-CO');

    $('#valor-venta-mostrar').text(valor_formateado);
}

/**
 * Actualizar el valor de venta total desde los inputs cuando se modifican manualmente.
 *
 * @returns {void}
 * @author Andres Gonzalez
 * @author Jair Carvajal
 */
function actualizarValorDesdeInput() {
    let valor_plan = 0;
    let valor_creditos = 0;

    // Usar los campos visuales para mostrar el total
    let valor_plan_input = $('#precio_plan_visual').val();
    if (valor_plan_input) {
        valor_plan = parseFloat(valor_plan_input.replace(/[^\d]/g, '')) || 0;
    }

    let valor_creditos_input = $('#precio_creditos_visual').val();
    if (valor_creditos_input) {
        valor_creditos = parseFloat(valor_creditos_input.replace(/[^\d]/g, '')) || 0;
    }

    // Sincronizar campos hidden que realmente se envían al backend.
    let tiene_valor_plan = valor_plan_input && valor_plan_input.replace(/[^\d]/g, '') !== '';
    if ($('#precio_plan_visual').length) {
        $('#precio_plan_original').val(tiene_valor_plan ? valor_plan : '');
    }
    let tiene_valor_creditos = valor_creditos_input && valor_creditos_input.replace(/[^\d]/g, '') !== '';
    if ($('#precio_creditos_visual').length) {
        $('#precio_creditos_original').val(tiene_valor_creditos ? valor_creditos : '');
    }

    let valor_antecedentes = 0;
    let valor_antecedentes_input = $('#precio_antecedentes_visual').val();
    if (valor_antecedentes_input) {
        valor_antecedentes = parseFloat(valor_antecedentes_input.replace(/[^\d]/g, '')) || 0;
    }
    let tiene_valor_antecedentes = valor_antecedentes_input && valor_antecedentes_input.replace(/[^\d]/g, '') !== '';
    if ($('#precio_antecedentes_visual').length) {
        $('#precio_antecedentes_original').val(tiene_valor_antecedentes ? valor_antecedentes : '');
    }

    let valor_total = valor_plan + valor_creditos + valor_antecedentes;

    // Formatear el valor con separador de miles
    let valor_formateado = valor_total.toLocaleString('es-CO');

    $('#valor-venta-mostrar').text(valor_formateado);
}

/**
 * Aplicar el porcentaje de descuento al valor del plan o créditos.
 *
 * @param {string} tipo - Tipo de plan: "plan" o "creditos"
 * @returns {void}
 * @author Andres Gonzalez
 * @author Jair Carvajal
 */
function aplicarDescuento(tipo) {
    let campo_porcentaje = tipo === 'plan' ? '#porcentaje_descuento' : (tipo === 'creditos' ? '#porcentaje_descuento_creditos' : '#porcentaje_descuento_antecedentes');
    let campo_visual = tipo === 'plan' ? '#precio_plan_visual' : (tipo === 'creditos' ? '#precio_creditos_visual' : '#precio_antecedentes_visual');

    let porcentaje = parseFloat($(campo_porcentaje).val()) || 0;
    let valor_original = 0;
    if (tipo === 'plan' && plan_seleccionado && plan_seleccionado.precio) {
        valor_original = parseFloat(plan_seleccionado.precio) || 0;
    } else if (tipo === 'creditos' && plan_creditos_seleccionado && plan_creditos_seleccionado.precio) {
        valor_original = parseFloat(plan_creditos_seleccionado.precio) || 0;
    } else if (tipo === 'antecedentes' && plan_antecedentes_seleccionado && plan_antecedentes_seleccionado.precio) {
        valor_original = parseFloat(plan_antecedentes_seleccionado.precio) || 0;
    }

    if (porcentaje > 0 && porcentaje <= 100 && valor_original > 0) {
        let descuento = valor_original * (porcentaje / 100);
        let valor_con_descuento = Math.round(valor_original - descuento);
        $(campo_visual).val(valor_con_descuento);
        $(campo_visual).prop('disabled', true);
    } else {
        if (valor_original > 0) {
            $(campo_visual).val(valor_original);
        }
        $(campo_visual).prop('disabled', false);
    }

    actualizarValorDesdeInput();
}

/**
 * Abrir la factura del plan en una nueva pestaña del navegador.
 * 
 * @param {number} factura_id Id de la factura.
 * @returns {void}
 * @author Andres Morales
 */
async function abrirFacturaPlan(factura_id) {
    if (!factura_id) {
        mostrarToast('danger', 'No se encontró la factura');
        return;
    }
    try {
        const respuesta = await $.ajax({
            type: 'GET',
            url: `/archivos-abrir/${factura_id}`,
            xhrFields: { responseType: 'blob' }
        });
        const blobUrl = window.URL.createObjectURL(respuesta);
        window.open(blobUrl, '_blank');
    } catch (error) {
        mostrarToast('danger', 'Ocurrió un error al intentar abrir la factura');
    }
}
/**
 * Buscar las funcionalidades por tipo de prueba.
 * @param {number} tipo_prueba_id ID del tipo de prueba.
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Daniel Beltrán
 */
function buscarfuncionalidades(tipo_prueba_id) {
    $.ajax({
        type : 'GET',
        url : `/funcionalidades-listado`,
        data : {
            tipo_prueba_id: tipo_prueba_id,
            incluir_tipo_prueba_null: true
        },
        success: function(respuesta) {
            let beneficios = respuesta.data;
            const ADICIONALES = beneficios
                .filter(item => item.predeterminado === 0)
                .map(({ id, nombre, predeterminado }) => ({ id, nombre, predeterminado }))
                .sort((a, b) => b.id - a.id);
            const PREDEFINIDOS = beneficios
                .filter(item => item.predeterminado === 1)
                .map(({ id, nombre, predeterminado }) => ({ id, nombre, predeterminado }))
                .sort((a, b) => b.id - a.id);
            funcionalidades_predefinidos = PREDEFINIDOS;
            // Verificar si el multiselect está inicializado antes de destruir
            if ($('#adicionales_modal').data('multiselect')) {
                $('#adicionales_modal').multiselect('destroy');
            }
            if ($('#predefinidos_modal').data('multiselect')) {
                $('#predefinidos_modal').multiselect('destroy');
            }
            ADICIONALES.forEach((item) => {
                $('#adicionales_modal').append(`<option value="${item.id}">${item.nombre}</option>`);
            });
            PREDEFINIDOS.forEach((item) => {
                $('#predefinidos_modal').append(`<option value="${item.id}">${item.nombre}</option>`);
            });
            inizializarMultiselect();
            if (opcion == 'facturar' || opcion == 'editar') {
                buscarfuncionalidadesPlanEmpresa($('#id').val());
            }
        },
        error: function(error) {
            console.log(error);
        }
    });
}
/**
 * Buscar las funcionalidades del plan de la empresa.
 * @param {number} empresa_plan_id ID del plan de empresa.
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Daniel Beltrán
 */
function buscarfuncionalidadesPlanEmpresa(empresa_plan_id) {
    $.ajax({
        type : 'GET',
        url : `/empresas-planes-funcionalidades-listado`,
        data : {
            empresa_plan_id: empresa_plan_id,
            incluir_tipo_prueba_null: true
        },
        success: function(respuesta) {
            let funcionalidades = respuesta.data.map(item => item.funcionalidad_id);
            $('#adicionales_modal').val(funcionalidades);
            // Verificar si el multiselect está inicializado antes de refrescar
            if ($('#adicionales_modal').data('multiselect')) {
                $('#adicionales_modal').multiselect("refresh");
            }
            $('#predefinidos_modal').val(funcionalidades);
            if ($('#predefinidos_modal').data('multiselect')) {
                $('#predefinidos_modal').multiselect("refresh");
            }
        },
        error: function(error) {
            console.log(error);
        }
    });
}
/**
 * Función para agregar validaciones adicionales y data adicional en el envío del form.
 * @returns {void}
 * @author José Manuel Jiménez
 */
function validacionAdicional() {
    let valido = true;
    let es_solo_creditos = plan_seleccionado === null && plan_creditos_seleccionado !== null;
    $('#vigencia').val($('#vigencia_modal').val());
    if ($('#unidades_modal').val() == 'Ilimitadas') {
        $('#unidades').val('');
    } else {
        $('#unidades').val($('#unidades_modal').val());
    }
    if ($('#cantidad_ofertas_laborales_modal').val() == 'Ilimitadas') {
        $('#cantidad_ofertas_laborales').val('');
    } else {
        $('#cantidad_ofertas_laborales').val($('#cantidad_ofertas_laborales_modal').val());
    }
    $('#cantidad_usuarios').val($('#cantidad_usuarios_modal').val());
    $('#cantidad_pruebas').val($('#cantidad_pruebas_modal').val());
    if (opcion == 'facturar' || opcion == 'editar') {
        let adicionales = $('#adicionales_modal').val();
        let predefinidos = $('#predefinidos_modal').val();
        let funcionalidades = adicionales.concat(predefinidos);
        $('#funcionalidades').val(JSON.stringify(funcionalidades));
        if (!es_solo_creditos && funcionalidades.length == 0) {
            valido = false;
            mostrarToast('danger', 'Seleccione al menos una funcionalidad.');
        }
    } else {
        let ids = [];
        if (plan_seleccionado && Array.isArray(plan_seleccionado.funcionalidades)) {
            ids = plan_seleccionado.funcionalidades.map(objeto => objeto.id);
        }
        $('#funcionalidades').val(JSON.stringify(ids));
    }
    var pruebas_seleccionadas = $('.pruebas:checked').map(function() {
        return this.value;
    }).get();
    $('#pruebas').val('');
    let maximo_pruebas = $('#cantidad_pruebas_modal').val();
    if (maximo_pruebas == '') {
        maximo_pruebas = plan_seleccionado ? plan_seleccionado.cantidad_pruebas : 0;
    }
    if (!es_solo_creditos) {
        if (pruebas_seleccionadas.length == 0) {
            valido = false;
            mostrarToast('danger', 'Seleccione al menos una prueba.');
        } else if (pruebas_seleccionadas.length > maximo_pruebas) {
            valido = false;
