   890→/**
   891→ * Aplicar el porcentaje de descuento al valor del plan o créditos.
   892→ *
   893→ * @param {string} tipo - Tipo de plan: "plan" o "creditos"
   894→ * @returns {void}
   895→ * @author Andres Gonzalez
   896→ * @author Jair Carvajal
   897→ */
   898→function aplicarDescuento(tipo) {
   899→    let campo_porcentaje = tipo === 'plan' ? '#porcentaje_descuento' : (tipo === 'creditos' ? '#porcentaje_descuento_creditos' : '#porcentaje_descuento_antecedentes');
   900→    let campo_visual = tipo === 'plan' ? '#precio_plan_visual' : (tipo === 'creditos' ? '#precio_creditos_visual' : '#precio_antecedentes_visual');
   901→
   902→    let porcentaje = parseFloat($(campo_porcentaje).val()) || 0;
   903→    let valor_original = 0;
   904→    if (tipo === 'plan' && plan_seleccionado && plan_seleccionado.precio) {
   905→        valor_original = parseFloat(plan_seleccionado.precio) || 0;
   906→    } else if (tipo === 'creditos' && plan_creditos_seleccionado && plan_creditos_seleccionado.precio) {
   907→        valor_original = parseFloat(plan_creditos_seleccionado.precio) || 0;
   908→    } else if (tipo === 'antecedentes' && plan_antecedentes_seleccionado && plan_antecedentes_seleccionado.precio) {
   909→        valor_original = parseFloat(plan_antecedentes_seleccionado.precio) || 0;
   910→    }
   911→
   912→    if (porcentaje > 0 && porcentaje <= 100 && valor_original > 0) {
   913→        let descuento = valor_original * (porcentaje / 100);
   914→        let valor_con_descuento = Math.round(valor_original - descuento);
   915→        $(campo_visual).val(valor_con_descuento);
   916→        $(campo_visual).prop('disabled', true);
   917→    } else {
   918→        if (valor_original > 0) {
   919→            $(campo_visual).val(valor_original);
   920→        }
   921→        $(campo_visual).prop('disabled', false);
   922→    }
   923→
   924→    actualizarValorDesdeInput();
   925→}
