                            <button type="button" id="elegir-plan-2" class="btn btn-outline-primary mx-1 my-1" onclick="modalElegirPlan(2);">
                                Elegir Plan de Créditos IA
                            </button>
                        </div>
                    </div>
                </div>
            `;
            $('#contenedor-creditos').html(seccion_creditos);
        }
    } else {
        // Si se deseleccionó el tipo de créditos, limpiar el plan de créditos
        $('#contenedor-creditos').empty();
        $('#contenedor-plan-creditos').remove();
        plan_creditos_seleccionado = null;
        $('#plan_credito_id').val('');
        $('#creditos').val('');
    }
    // Manejo del plan de antecedentes
    if (tiene_antecedentes) {
        if (plan_antecedentes_seleccionado === null && $('#contenedor-antecedentes').children().length === 0) {
            let seccion_antecedentes = `
                <div class="mt-3" id="contenedor-plan-antecedentes-inner">
