                                Elegir Plan de Antecedentes
                            </button>
                        </div>
                    </div>
                </div>
            `;
            $('#contenedor-antecedentes').html(seccion_antecedentes);
        }
    } else {
        $('#contenedor-antecedentes').empty();
        plan_antecedentes_seleccionado = null;
        $('#plan_antecedente_id').val('');
        $('#consultas_antecedentes').val('');
        $('#contenedor-precio-antecedentes').addClass('d-none');
    }
    $.ajax({
        type: 'GET',
        url : `/pruebas-listado`,
        data: {
