/**
 * Obtener el listado de planes según el tipo_prueba_id seleccionado anteriormente.
 * @param {number|null} tipo_especifico ID del tipo de prueba específico (opcional).
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Jair Carvajal
 */
function modalElegirPlan(tipo_especifico = null) {
    let tipo_prueba_para_consulta = tipo_especifico !== null ? tipo_especifico : $('#tipo_prueba_id').val();
    // Si es tipo 2 (Créditos IA), cargar planes de créditos
    if (tipo_prueba_para_consulta == 2 || tipo_prueba_para_consulta == '2') {
        $.ajax({
            type: 'GET',
            url: '/planes-creditos',
            data: {
                activo: true
            }
        }).then((respuesta) => {
            planes_creditos = respuesta.data.planes;
            mostrarPlanesCreditos();
        }).catch((error) => {
            mostrarToast('danger', 'Ocurrió un error');
        });
        return;
    }

    // TODO: Reemplazar data quemada
    if (tipo_prueba_para_consulta == 3 || tipo_prueba_para_consulta == '3') {
        planes_antecedentes = [
            { id: 1, nombre: 'Plan Básico Antecedentes', precio: 150000, consultas: 10, empresas_activas: 3 },
            { id: 2, nombre: 'Plan Estándar Antecedentes', precio: 350000, consultas: 30, empresas_activas: 7 },
            { id: 3, nombre: 'Plan Premium Antecedentes', precio: 800000, consultas: 100, empresas_activas: 12 },
        ];
        mostrarPlanesAntecedentes();
        return;
    }

    $.ajax({
        type: 'GET',
        url : `/planes-listado`,
        data: {
            tipo_prueba_id: $('#tipo_prueba_id').val()
        }
    }).then((respuesta) => {
        planes = respuesta.data;
        mostrarPlanes();
    }).catch((error) => {
        console.error(error);
    });
}
/**
 * Mostrar los planes de créditos en el modal.
 * @returns {void}
 * @author Jair Carvajal
 */
function mostrarPlanesCreditos() {
    let filtro_orden = $('#filtro-plan-credito').val();
    let buscar = $('#buscador-plan-credito').val() || '';
    // Ordenar planes según el filtro
    let planes_ordenados = [...planes_creditos];
    if (filtro_orden === 'Mayor') {
        planes_ordenados.sort((a, b) => b.creditos - a.creditos);
    } else if (filtro_orden === 'Menor') {
        planes_ordenados.sort((a, b) => a.creditos - b.creditos);
    }
    if (buscar !== '') {
        planes_ordenados = planes_ordenados.filter(plan =>
            plan.nombre.toLowerCase().includes(buscar.toLowerCase())
        );
    }
    $('#contenedor-planes-creditos').empty();
    if (planes_ordenados.length === 0) {
        $('#contenedor-planes-creditos').append(`
            <div class="text-center py-5">
                <p class="text-muted">No se encontraron planes</p>
            </div>
        `);
    }
    for (let i = 0; i < planes_ordenados.length; i++) {
        let plan = planes_ordenados[i];
        let creditos_disponibles = plan.creditos_disponibles || plan.creditos || 0;
        let creditos_promedio = plan.creditos_promedio_accion || 0;
        let acciones_estimadas = creditos_disponibles > 0 && creditos_promedio > 0
            ? Math.floor(creditos_disponibles / creditos_promedio)
            : 0;
        $('#contenedor-planes-creditos').append(`
            <div class="card rounded rounded-3 border-hover pointer mb-3" onclick="elegirPlanCreditos(${i}, ${filtro_orden === 'Mayor' ? 'true' : 'false'});">
                <div class="row align-items-center m-0 w-100 px-3 py-4">
                    <div class="col">
                        <div class="text-headline-6 text-gray-10">${plan.nombre}</div>
                    </div>
                    <div class="col-auto">
                        ${crearTag({
                            texto: 'Créditos disponibles: ' + plan.creditos.toLocaleString('es-CO'),
                            class: 'tag-tonal-yellow',
                        })}
                    </div>
                    <div class="col-auto text-primary fw-bold">
                        ${crearTag({
                            texto: 'Acciones estimadas: ' + acciones_estimadas.toLocaleString('es-CO'),
                            class: 'tag-tonal-yellow',
                        })}
                    </div>
                </div>
            </div>
        `);
    }
    if (typeof $.fn.modal !== 'undefined') {
        $('#modal-planes-creditos').modal('show');
    }
    $('#buscador-plan-credito').off('input').on('input', function() {
        mostrarPlanesCreditos();
    });
}
/**
 * Elegir un plan de créditos IA.
 * @param {number} indice Índice del plan en el array.
 * @param {boolean} orden_mayor Si está ordenado de mayor a menor.
 * @returns {void}
 * @author Jair Carvajal
 */
function elegirPlanCreditos(indice, orden_mayor = false) {
    // Aplicar el mismo ordenamiento que en mostrarPlanesCreditos
    let planes_ordenados = [...planes_creditos];
    if (orden_mayor) {
        planes_ordenados.sort((a, b) => b.creditos - a.creditos);
    } else {
        planes_ordenados.sort((a, b) => a.creditos - b.creditos);
