 * @param {number|null} tipo_especifico ID del tipo de prueba específico (opcional).
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Daniel Beltrán
 */
function mostrarPlanes() {
    let buscar = $('#buscador-plan').val();
    let filtro_plan = $('#filtro-plan').val();
    if ($.fn.DataTable.isDataTable('#tabla-planes')) {
        table.destroy();
    }
    $('#buscador-plan').remove();
    $('#tbody-planes').empty();
    for (let i = 0; i < planes.length; i++) {
        if (
            (filtro_plan == 'Todos') ||
            (filtro_plan == 'Ofertas' && planes[i].cantidad_ofertas_laborales != null) ||
            (filtro_plan == 'Unidades' && planes[i].unidades != null) ||
            (filtro_plan == 'Tiempo' && planes[i].vigencia != null)
        ) {
