                            class: 'bg-scale-yellow-90',
                        })}
                    </div>
                </div>
            </div>
        </div>
    `;
    $('#contenedor-antecedentes').html(seccion_antecedentes);
    $('#contenedor-precio-antecedentes').removeClass('d-none');
    if (plan_antecedentes_seleccionado && plan_antecedentes_seleccionado.precio) {
