/**
 * Abrir el modal de confirmación.
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Daniel Beltrán
 */
function abrirModalEstasSeguro() {
    // Verificar si Bootstrap modal está disponible antes de usar
    if (typeof $.fn.modal !== 'undefined') {
        $('#modal-modificar-planes').modal('hide');
        $('#modal-estas-seguro').modal('show');
    }
}
/**
 * Cancelar la edición de un plan.
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Daniel Beltrán
 */
function cancelarEdicion() {
    modificado = false;
    // Verificar si Bootstrap modal está disponible antes de usar
    if (typeof $.fn.modal !== 'undefined') {
        $('#modal-estas-seguro').modal('hide');
    }
    limpiarAdicional();
    mostrarPlanSeleccionado();
}
/**
 * Confirmar los datos editados.
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Daniel Beltrán
 */
function confirmarEdicion() {
    modificado = true;
    // Verificar si Bootstrap modal está disponible antes de usar
    if (typeof $.fn.modal !== 'undefined') {
        $('#modal-estas-seguro').modal('hide');
    }
    $('#plan-modificado').text('(modificado)');
    mostrarPlanSeleccionado();
}
/**
 * Limpiar los campos del modal.
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Daniel Beltrán
 */
function limpiarAdicional() {
    $('#cantidad_pruebas_modal').val('').trigger('change').trigger('select2:select');
    $('#tiempo_modal').val('').trigger('change').trigger('select2:select');
    $('#unidades_modal').val('');
    $('#cantidad_ofertas_laborales_modal').val('');
    $('#cantidad_usuarios_modal').val('');
    // Verificar si el multiselect está inicializado antes de llamar uncheckAll
    if ($('#adicionales_modal').data('multiselect')) {
        $('#adicionales_modal').multiselect("uncheckAll");
    }
    if ($('#predefinidos_modal').data('multiselect')) {
        $('#predefinidos_modal').multiselect("uncheckAll");
    }
}
/**
 * Función para ejecutar acciones luego de guardar.
 * @returns {void}
 * @author José Manuel Jiménez
 */
function postSuccess(respuesta) {
    limpiarFormulario(respuesta.formulario);
