public function guardar(Request $request): EmpresaPlan {
    $tiene_plan_seleccion    = $request->filled('plan_id');
    $tiene_plan_creditos     = $request->filled('plan_credito_id');
    $tiene_plan_antecedentes = $request->filled('plan_antecedente_id');
    $plan_asignado           = null;

    if ($tiene_plan_seleccion) {
        $plan_asignado = $this->guardarPlanSeleccion($request);
    }

    if ($tiene_plan_creditos) {
        $plan_creditos = $this->guardarPlanCreditos($request);

        if (!$tiene_plan_seleccion) {
            $plan_asignado = $plan_creditos;
        }
    }

    if ($tiene_plan_antecedentes) {
        $plan_antecedentes = $this->guardarPlanAntecedentes($request);

        if (!$tiene_plan_seleccion && !$tiene_plan_creditos) {
            $plan_asignado = $plan_antecedentes;
        }
    }

    return $plan_asignado;
}

