/**
 * Guardar un plan de antecedentes.
 *
 * @param Request $request Contenido de la petición.
 * @return EmpresaPlan
 * @author Andres Gonzalez
 */
protected function guardarPlanAntecedentes(Request $request): EmpresaPlan {
    $enviar_correo    = false;
    $plan_antecedente = $this->plan_antecedente_repositorio->getUno($request->plan_antecedente_id);
    $plan_activo      = $this->repositorio->planAntecedentesActivo($request->empresa_id);

    // Preparar datos para el plan de antecedentes
    $datos_antecedentes = [
        'empresa_id'           => $request->empresa_id,
        'plan_id'              => null,
        'plan_antecedente_id'  => $request->plan_antecedente_id,
        'consultas'            => $plan_antecedente->consultas ?? 0,
        'precio'               => $request->precio_antecedentes ?? $plan_antecedente->precio ?? null,
        'porcentaje_descuento' => $request->porcentaje_descuento_antecedentes ?? null,
        'numero_factura'       => $request->numero_factura,
        'comentario'           => $request->comentario,
        'fecha_inicio'         => null,
        'fecha_vencimiento'    => null,
        'usuario_id'           => auth()->user()->id ?? 2,
    ];

    // Si es edición de un plan de antecedentes existente
    if ($request->filled('id')) {
        if ($request->hasFile('factura')) {
            $archivo = $this->archivo_repositorio->obtenerPorModelo('App\Models\Empresas\EmpresaPlan', $request->id);

            if (!is_null($archivo)) {
                $this->eliminarArchivoDesdeRuta($archivo->ruta);
                $this->archivo_repositorio->eliminar($archivo->id);
            }
        }

        $plan_asignado = $this->repositorio->actualizar($request->id, $datos_antecedentes);
    } else {
        if (!is_null($plan_activo) && $plan_activo->id != $request->id) {
            $datos_antecedentes['estado_id'] = Plan::ESTADO_PROXIMO_ID;
        } else {
            $datos_antecedentes['estado_id'] = Plan::ESTADO_ACTIVO_ID;
        }

        $enviar_correo = true;
        $plan_asignado = $this->repositorio->crear($datos_antecedentes);
    }

    if ($request->hasFile('factura')) {
        $this->guardarFactura($plan_asignado->id, $request->empresa_id, $request->file('factura'));
    }

    return $plan_asignado;
}

