function seleccionarTipoPruebaMultiple() {
    let tipos_prueba = $('#tipo_prueba_id').val() || [];
    tipos_prueba = tipos_prueba.filter(function(tipo_id) {
        return tipo_id !== null && tipo_id !== '' && tipo_id !== undefined;
    });
    if (tipos_prueba.length === 0) {
        // Si no hay tipos seleccionados, limpiar todo
        $('#contenedor-plan').empty();
        $('#contenedor-creditos').empty();
        $('#seccion-pruebas').addClass('d-none');
        $('#plan_id').val('');
        $('#plan_id').prop('required', false);
        $('#plan_id').prop('disabled', true);
        $('#plan_credito_id').val('');
        $('#creditos').val('');
        plan_seleccionado = null;
        plan_creditos_seleccionado = null;
        pruebas = [];
        return;
    }
    let tiene_seleccion = tipos_prueba.includes('1') || tipos_prueba.includes(1);
    let tiene_creditos = tipos_prueba.includes('2') || tipos_prueba.includes(2);
    let tiene_antecedentes = tipos_prueba.includes('3') || tipos_prueba.includes(3);
    $('#plan_id').prop('required', tiene_seleccion);
    $('#plan_id').prop('disabled', !tiene_seleccion);
