function seleccionarTipoPrueba(tipo_prueba_id) {
    $('#contenedor-plan').empty();
    $('#contenedor-plan').append(`
        <div class="card-body text-center">
            <button type="button" id="elegir-plan" class="btn btn-outline-primary" disabled onclick="modalElegirPlan();">Elegir plan</button>
        </div>
    `);
    $('#seccion-pruebas').addClass('d-none');
    $('#plan_id').val('');
    pruebas = [];
    // Convertir tipo_prueba_id a array si no lo es
    let tipos_prueba = Array.isArray(tipo_prueba_id) ? tipo_prueba_id : [tipo_prueba_id];
    // Crear los botones según los tipos de prueba seleccionados
    let botones_html = '<div class="card-body text-center">';
    tipos_prueba.forEach(function(tipo_id) {
        let texto_boton = 'Elegir plan';
        let clase_boton = 'btn-outline-primary';
        if (tipo_id == 1) {
            texto_boton = 'Elegir Plan de Selección';
            clase_boton = 'btn-outline-primary';
        } else if (tipo_id == 2) {
            texto_boton = 'Elegir Plan de Créditos IA';
            clase_boton = 'btn-outline-info';
        } else if (tipo_id == 3) {
            texto_boton = 'Elegir Plan de Antecedentes';
            clase_boton = 'btn-outline-success';
        }
        botones_html += `
            <button type="button" id="elegir-plan-${tipo_id}" class="btn ${clase_boton} mx-1 my-1" disabled onclick="modalElegirPlan(${tipo_id});">
                ${texto_boton}
            </button>
        `;
    });
    botones_html += '</div>';
    $('#contenedor-plan').append(botones_html);
    $('#tipo_prueba_id').val(tipo_prueba_id).trigger('select2');
    if (tipo_prueba_id && (Array.isArray(tipo_prueba_id) ? tipo_prueba_id.length > 0 : tipo_prueba_id)) {
        // Habilitar todos los botones creados
        tipos_prueba.forEach(function(tipo_id) {
            $(`#elegir-plan-${tipo_id}`).prop('disabled', false);
        });
        $.ajax({
            type: 'GET',
            url : `/pruebas-listado`,
            data: {
                tipo_prueba_id: tipo_prueba_id,
                activo: 1
            }
        }).then((respuesta) => {
            limpiarAdicional();
            $('#contenedor-pruebas').empty();
            pruebas = respuesta.data;
            for (let i = 0; i < pruebas.length; i++) {
                $('#contenedor-pruebas').append(`
                    <div class="col-12 col-md-6">
                        <div class="d-flex align-items-center">
                            <div class="check-container my-1 me-1">
                                <input type="checkbox" id="prueba-${pruebas[i].id}" name="prueba-${pruebas[i].id}" value="${pruebas[i].id}" class="form-check-input input-dinamico pruebas" onchange="ValidarPruebas();">
                            </div>
                            <label class="text-label-1" for="prueba-${pruebas[i].id}">${pruebas[i].nombre}</label>
                        </div>
                    </div>
                `);
            }
            if (opcion == 'facturar' || opcion == 'editar') {
                for (let i = 0; i < pruebas_empresa_plan.length; i++) {
                    $(`#prueba-${pruebas_empresa_plan[i].id}`).prop('checked', true);
                }
                $('#seccion-pruebas').removeClass('d-none');
                mostrarPlanSeleccionado();
            }
            if (opcion == 'editar') {
                $('#tipo_prueba_id').prop('disabled', true);
            }
        }).catch((error) => {
            console.error(error);
        });
    } else {
        $('#elegir-plan').prop('disabled', true);
    }
