 * @returns {void}
 * @author Jair Carvajal
 */
function elegirPlanCreditos(indice, orden_mayor = false) {
    // Aplicar el mismo ordenamiento que en mostrarPlanesCreditos
    let planes_ordenados = [...planes_creditos];
    if (orden_mayor) {
        planes_ordenados.sort((a, b) => b.creditos - a.creditos);
    } else {
        planes_ordenados.sort((a, b) => a.creditos - b.creditos);
    }
    plan_creditos_seleccionado = planes_ordenados[indice];
    // Establecer los valores en los campos hidden
    $('#plan_credito_id').val(plan_creditos_seleccionado.id);
    $('#creditos').val(plan_creditos_seleccionado.creditos);
    mostrarPlanCreditosSeleccionado();
    if (typeof $.fn.modal !== 'undefined') {
        $('#modal-planes-creditos').modal('hide');
    }
}
