/**
 * Mostrar los planes de antecedentes en el modal.
 *
 * @returns {void}
 * @author Jair Carvajal
 */
function mostrarPlanesAntecedentes() {
    let filtro_orden = $('#filtro-plan-antecedente').val() || 'Mayor';
    let buscar = $('#buscador-plan-antecedente').val() || '';
    let planes_ordenados = [...planes_antecedentes];
    if (filtro_orden === 'Mayor') {
        planes_ordenados.sort((a, b) => b.consultas - a.consultas);
    } else if (filtro_orden === 'Menor') {
        planes_ordenados.sort((a, b) => a.consultas - b.consultas);
    }
    if (buscar !== '') {
        planes_ordenados = planes_ordenados.filter(plan =>
            plan.nombre.toLowerCase().includes(buscar.toLowerCase())
        );
    }
    $('#contenedor-planes-antecedentes').empty();
    if (planes_ordenados.length === 0) {
        $('#contenedor-planes-antecedentes').append(`
            <div class="text-center py-5">
                <p class="text-muted">No se encontraron planes</p>
            </div>
        `);
    }
    for (let i = 0; i < planes_ordenados.length; i++) {
        let plan = planes_ordenados[i];
        $('#contenedor-planes-antecedentes').append(`
            <div class="card rounded rounded-3 border-hover pointer mb-3" onclick="elegirPlanAntecedentes(${i}, ${filtro_orden === 'Mayor' ? 'true' : 'false'});">
                <div class="row align-items-center m-0 w-100 px-3 py-4">
                    <div class="col">
                        <div class="text-headline-6 text-gray-10">${plan.nombre}</div>
                    </div>
                    <div class="col-auto">
                        ${crearTag({
                            texto: 'Consultas incluidas: ' + plan.consultas.toLocaleString('es-CO'),
                            class: 'bg-scale-yellow-90',
                        })}
                    </div>
                    <div class="col-auto text-primary fw-bold">
                        ${crearTag({
                            texto: '$ ' + plan.precio.toLocaleString('es-CO'),
                            class: 'bg-scale-yellow-90',
                        })}
                    </div>
                </div>
            </div>
        `);
    }
    if (typeof $.fn.modal !== 'undefined') {
        $('#modal-planes-antecedentes').modal('show');
    }
    $('#buscador-plan-antecedente').off('input').on('input', function() {
        mostrarPlanesAntecedentes();
    });
}

/**
 * Elegir un plan de antecedentes.
 *
 * @param {number} indice Índice del plan en el array.
 * @param {boolean} orden_mayor Si está ordenado de mayor a menor.
 * @returns {void}
 * @author Jair Carvajal
 */
function elegirPlanAntecedentes(indice, orden_mayor = false) {
    let planes_ordenados = [...planes_antecedentes];
    if (orden_mayor) {
        planes_ordenados.sort((a, b) => b.consultas - a.consultas);
    } else {
        planes_ordenados.sort((a, b) => a.consultas - b.consultas);
