 * Obtener todos los planes de antecedentes activos de la empresa.
 *
 * @param int $empresa_id ID de la empresa.
 * @return Collection
 * @author Andres Gonzalez
 */
public function obtenerPlanesAntecedentesActivos(int $empresa_id): Collection {
    $planes       = $this->repositorio->planesAntecedentesActivos($empresa_id);
    $plan_proximo = $this->repositorio->planAntecedentesProximo($empresa_id);

    return $planes->map(function ($plan) use ($plan_proximo) {
        $plan->plan_proximo_id = $plan_proximo?->id ?? null;

        $total_consultas           = $plan->consultas ?? $plan->planAntecedente?->consultas ?? 0;
        $consultas_consumidas      = (int) ($plan->consultas_consumidas ?? 0);
        $plan->consultas_restantes = max(0, $total_consultas - $consultas_consumidas);

        return $plan;
    });
}

/**
 * Obtener el último plan de la empresa por tipo de prueba excluyendo los que tengan estado próximo.
 *
 * @param int $empresa_id ID de la empresa.
 * @param int $tipo_prueba_id ID del tipo de prueba.
 * @return ?EmpresaPlan
 * @author Daniel Beltrán
 */
public function obtenerUltimoPorTipo(int $empresa_id, int $tipo_prueba_id): ?EmpresaPlan {
    $plan = $this->repositorio->ultimoPlanAsignado(new Request([
        'empresa_id'             => $empresa_id,
        'tipo_prueba_id'         => $tipo_prueba_id,
        'excluir_estado_proximo' => true
    ]));

    if (!is_null($plan)) {
        $plan_proximo       = $this->repositorio->planProximo($empresa_id, $tipo_prueba_id);
        $plan->plan_proximo = !is_null($plan_proximo) && $plan->id !== $plan_proximo->id;
    }

