/**
 * Función para formatear la hora
 *
 * @param {number} timestamp fecha a transformar.
 * @returns {Promise<Array>}
 * @author Jair Carvajal
 */
function obtenerFechaHora(timestamp) {
  // Crear objeto Date a partir del timestamp ISO
  let fecha = new Date(timestamp);
  // Extraer fecha en formato YYYY-MM-DD
  let fechaStr = fecha.toISOString().split("T")[0];
  // Extraer hora en formato HH:MM:SS
  let horaStr = fecha.toISOString().split("T")[1].split(".")[0];

  return {
    fecha: fechaStr,
    hora: horaStr
  };
}

