        $('#nombre-plan').text(plan.plan.nombre);
        $('#unidades-plan').text(plan.unidades);
        $('#tiempo-plan').text(plan.vigencia_dias + ' Días');
        $('#usuarios-plan').text(plan.plan.cantidad_usuarios);
        $('#ofertas-laborales-plan').text(plan.cantidad_ofertas_laborales);
        $('#nav-actual-tab').click();
        if (plan.plan_proximo ) {
            $('#nombre-plan-proximo').text(plan.plan_proximo.plan.nombre);
            $('#unidades-plan-proximo').text(plan.plan_proximo.unidades);
            $('#tiempo-plan-proximo').text(plan.plan_proximo.vigencia_dias + ' Días');
            $('#usuarios-plan-proximo').text(plan.plan_proximo.cantidad_usuarios);
            $('#ofertas-laborales-plan-proximo').text(plan.plan_proximo.cantidad_ofertas_laborales);
            $('#contenedor-alert-proximo').removeClass('d-none');
            $('#nav-tab-plan').removeClass('d-none');
        } else {
            $('#contenedor-alert-proximo').addClass('d-none');
            $('#nav-tab-plan').addClass('d-none');
        }
        $('#modal-detalle-plan').modal('show');
    }).catch((error) => {
        console.error(error);
    });
}

//APARTADO PARA GESTIONAR EMPRESAS
let usuarios = [];
let empresa_seleccionada = null;
let configuraciones_defecto = [];
let configuraciones_personalizadas = [];

/**
 * Obtener los datos del formulario de gestionar empresa.
 *
 * @param {number} empresa_id ID de la empresa.
 * @returns {void}
 * @author Daniel Beltrán
 * @author Esperanza Olivo
 */
function obtenerDatosGestionarEmpresa(empresa_id) {

    if (campo_celular_contacto === null) campo_celular_contacto = definirInputTipoCelular(CAMPO_CELULAR_CONTACTO_ID, CAMPO_CELULAR_CONTACTO_ID, 'Celular*');
    if (campo_celular === null) campo_celular = definirInputTipoCelular(CAMPO_CELULAR_ID, CAMPO_CELULAR_ID, 'Celular*');
    if (campo_celular_tesorero === null) campo_celular_tesorero = definirInputTipoCelular(CAMPO_CELULAR_TESORERO_ID, CAMPO_CELULAR_TESORERO_ID, 'Celular*');
    if (campo_celular_usuario === null) campo_celular_usuario = definirInputTipoCelular(CAMPO_CELULAR_USUARIO_ID, CAMPO_CELULAR_USUARIO_ID, 'Celular*', false);

    usuarios = [];
    usuarios_seleccionados = [];
    empresa_seleccionada = null;
    configuraciones_defecto = [];
    configuraciones_personalizadas = [];

    $('.id').val('');
    $('.empresa_id').val('');
    $('#usuario').val('');
    $('.col-lg-6-empresa').addClass('col-lg-6');
    $('#tabs-empresa').addClass('d-none');
    if (empresa_id != '' && empresa_id != null) {
        $.ajax({
            type : 'GET',
            url : `/empresas-gestionar-datos/${empresa_id}`,
            processData: false,
            contentType: false,
            success: function(respuesta) {
                let empresa = respuesta.data;
                if (empresa.activo == 0) {
                    $('#contenedor-estado-empresa').removeClass('d-none');
                } else {
                    $('#contenedor-estado-empresa').addClass('d-none').empty();
                }
                if (empresa.empresa_id != null) {
                    $('#boton-crear-usuarios').prop('href', `/usuarios/create?empresa_id=${empresa.id}`);
                    $('#boton-asignar-planes').prop('href', `/asignar-plan/${empresa.id}`);
                    $('#filtro_empresa_id').append(`
                        <option value="${empresa.empresa.id}">${empresa.empresa.razon_social}</option>
                    `);
                    if ($('#filtro_empresa_id').val() == '' || $('#filtro_empresa_id').val() == null) {
                        $('#filtro_empresa_id').val(empresa.empresa.id).trigger('change', {programmatic: true});
                    }
                    buscarSucursalesEmpresa(empresa.empresa.id, empresa.id);
                    $('.id').val(empresa.id);
                    $('.empresa_id').val(empresa.empresa.id);
                    $('.empresa').addClass('d-none');
                    $('.sucursal').removeClass('d-none');
                    $('.col-lg-6-empresa').removeClass('col-lg-6');
                    $('#ejecutivo-cuenta').text('Ejecutivo de cuenta: ' + empresa.ejecutivo.nombre_completo);
                    $('#seccion-logo').addClass('d-none');
                } else {
                    $('#boton-crear-usuarios').prop('href', `/usuarios/create?empresa_id=${empresa.id}`);
                    $('#boton-asignar-planes').prop('href', `/asignar-plan/${empresa.id}`);
                    $('#filtro_empresa_id').append(`
                        <option value="${empresa.id}">${empresa.razon_social}</option>
                    `);
                    if ($('#filtro_empresa_id').val() == '' || $('#filtro_empresa_id').val() == null) {
                        $('#filtro_empresa_id').val(empresa.id).trigger('change', {programmatic: true});
                    }
                    buscarSucursalesEmpresa(empresa_id);
                    $('.id').val(empresa.id);
                    $('.empresa').removeClass('d-none');
                    $('.sucursal').addClass('d-none');
                    $('#ejecutivo-cuenta').text('');
                    $('#seccion-logo').removeClass('d-none');
                }
                if (empresa.es_persona_juridica == 1) {
                    $("#es_persona_juridica_si").prop('checked', true);
                } else {
                    $("#es_persona_juridica_no").prop('checked', true);
                }
                $('#razon_social').val(empresa.razon_social);
                $('#nombre_comercial').val(empresa.nombre_comercial);
                let documento = empresa.documento.split('-');
                $('#documento').val(documento[0]);
                $('#digito_verificacion').val(documento[1]);
                $('#sector_id').val(empresa.sector_id).trigger('change').trigger('select2:select');
                $('#tamano_empresa_id').val(empresa.tamano_empresa_id).trigger('change').trigger('select2:select');
                $('#procesos_estimados_mensuales').val(empresa.procesos_estimados_mensuales);
                $('#pruebas_estimadas_mensuales').val(empresa.pruebas_estimadas_mensuales);
                $('#pais_id').data('departamento_id', empresa.ciudad.departamento_id);
                $('#pais_id').val(empresa.ciudad.departamento.pais_id).trigger('change').trigger('select2:select');
                $('#departamento_id').data('ciudad_id', empresa.ciudad.id);
                $('#departamento_id').val(empresa.departamento_id).trigger('change').trigger('select2:select');
                $('#ciudad_id').val(empresa.ciudad_id).trigger('change').trigger('select2:select');
                $('#direccion').val(empresa.direccion);
                $('#celular').val(empresa.celular);

                rellenarInputCelular(empresa.indicativo_celular, empresa.codigo_iso2_pais_celular, empresa.celular, CAMPO_CELULAR_ID, campo_celular);

                $('#email_facturacion').val(empresa.email_facturacion);
                $('#telefono').val(empresa.telefono);

                actualizarEnlacesPrevisualizacionArchivos(empresa.archivos);

                if (empresa.telefono_tesorero != null) {
                    let telefono = empresa.telefono_tesorero.split('-');
                    $('#telefono').val(telefono[0]);
                    $('#extension').val(telefono[1]);
                }

                $('#ejecutivo_id').val(empresa.ejecutivo_id).trigger('change').trigger('select2:select');
                $('#nombre_representante').val(empresa.nombre_representante);
                $('#tipo_documento_representante_id').val(empresa.tipo_documento_representante_id).trigger('change').trigger('select2:select');
                $('#documento_representante').val(empresa.documento_representante);
                $('#email_representante').val(empresa.email_representante);
                if (![undefined, null, ''].includes(empresa.id)) {
                    if (empresa.empresa_id != null) {
                        $.ajax({
                            type: 'GET',
                            url : `/empresas-logo/${empresa.id}`,
                            success: function() {
                                $('#logo_sucursal_fondo_previsualizacion').addClass('d-none');
                                $('#logo_sucursal_previsualizacion').attr('src', `/empresas-logo/${empresa.id}`);
                                $($('.hr-tab')[0]).addClass('border-blue-40 opacity-100');
                            }
                        });
                    } else {
                        $.ajax({
                            type: 'GET',
                            url : `/empresas-logo/${empresa.id}`,
                            success: function() {
                                $('#logo_fondo_previsualizacion').addClass('d-none');
                                $('#logo_previsualizacion').attr('src', `/empresas-logo/${empresa.id}`);
                                $($('.hr-tab')[0]).addClass('border-blue-40 opacity-100');
                            }
                        });
                    }
                }

                if (empresa.usuarios.length > 0) {
                    const USUARIO_EMPRESA = empresa.usuarios[0].usuario;

                    $('#usuario_id').val(USUARIO_EMPRESA.id);
                    $('#nombres').val(USUARIO_EMPRESA.nombres);
                    $('#apellidos').val(USUARIO_EMPRESA.apellidos);
                    $('#tipo_documento_id').val(USUARIO_EMPRESA.tipo_documento_id).trigger('change').trigger('select2:select');
                    $('#documento_usuario').val(USUARIO_EMPRESA.documento);
                    $('#email').val(USUARIO_EMPRESA.email);

                    rellenarInputCelular(
                        USUARIO_EMPRESA.indicativo_telefono,
                        USUARIO_EMPRESA.codigo_iso2_pais_telefono,
                        USUARIO_EMPRESA.telefono,
                        CAMPO_CELULAR_USUARIO_ID,
                        campo_celular_usuario
                    );

                    $('#usuario').val(JSON.stringify({
                        id               : USUARIO_EMPRESA.id,
                        tipo_documento_id: USUARIO_EMPRESA.tipo_documento_id,
                        documento        : USUARIO_EMPRESA.documento,
                        nombres          : USUARIO_EMPRESA.nombres,
                        apellidos        : USUARIO_EMPRESA.apellidos,
                        email            : USUARIO_EMPRESA.email,
                        telefono         : USUARIO_EMPRESA.telefono
                    }));
                }

                $('#nombre_tesorero').val(empresa.nombre_tesorero);
                $('#email_tesorero').val(empresa.email_tesorero);

                rellenarInputCelular(
                    empresa.indicativo_celular_tesorero,
                    empresa.codigo_iso2_pais_celular_tesorero,
                    empresa.celular_tesorero,
                    CAMPO_CELULAR_TESORERO_ID,
                    campo_celular_tesorero
                );

                if ( empresa.telefono_tesorero != null) {
                    let telefono_tesorero = empresa.telefono_tesorero.split('-');
                    $('#telefono_tesorero').val(telefono_tesorero[0]);
                    $('#extension_tesorero').val(empresa.telefono_tesorero[1]);
                }
                $('#nombre_contacto').val(empresa.nombre_contacto);
                $('#email_contacto').val(empresa.email_contacto);

                rellenarInputCelular(
                    empresa.indicativo_celular_contacto,
                    empresa.codigo_iso2_pais_celular_contacto,
                    empresa.celular_contacto,
                    CAMPO_CELULAR_CONTACTO_ID,
                    campo_celular_contacto
                );

                empresa_seleccionada = empresa;
                mostrarPlanes();
                $('#empresa-tab').click();
                $('#tabs-empresa').removeClass('d-none');
                usuarios = empresa.usuarios;
                mostrarUsuarios(empresa_id);
                configuraciones_defecto = empresa.configuraciones_defecto;
                configuraciones_personalizadas = empresa.configuraciones_personalizadas;
                let archivos = empresa.archivos;
                $('.contenedor-archivo').addClass('d-none');
                archivos.forEach((archivo) => {
                    $('#archivo_' + archivo.nombre).removeClass('d-none');
                    $('#archivo_' + archivo.nombre).prop('href', '/archivos-abrir/' + archivo.id);
                });

                mostrarConfiguraciones();
            },
            error: function(error) {
                console.log(error);
            }
        });
    } else if ($('#filtro_empresa_id').val() != '' && $('#filtro_empresa_id').val() != null) {
        obtenerDatosGestionarEmpresa($('#filtro_empresa_id').val());
        $('#tabs-empresa').removeClass('d-none');
    }
};

/**
 * Actualizar los elementos anchor de previsualización de archivos de la empresa.
 *
 * @param {array} archivos_empresa Arreglo de archivos de la empresa.
 * @param {boolean} reiniciar_campo_archivo Si se debe reiniciar el campo de archivo.
 * @returns {void}
 * @author Fahibram Cárcamo
 * @author Andres Gonzalez
 */
function actualizarEnlacesPrevisualizacionArchivos(archivos_empresa, reiniciar_campo_archivo = true) {
    // Oculta todos los elementos anchor de previsualización de archivos.
    $('.previsualizacion-archivo').addClass('d-none');

    // Muestra los elementos de previsualización de archivos que corresponden con los archivos
    // relacionados con la empresa.
    for (let i = 0; i < archivos_empresa.length; i++) {
        $('#archivo_' + archivos_empresa[i].nombre).prop('href', `/archivos-abrir/${archivos_empresa[i].id}`);
        $('#archivo_' + archivos_empresa[i].nombre).removeClass('d-none');

        let input_archivo = $('#' + archivos_empresa[i].nombre + '.input-file.input-form');
        let input_archivo_label = $('label[for="' + archivos_empresa[i].nombre + '"].nombre-archivo');
        let input_archivo_boton_eliminar = $('#boton-eliminar-archivo-' + archivos_empresa[i].nombre + '.eliminar-archivo');

        if(reiniciar_campo_archivo) {
            reiniciarCampoArchivo(input_archivo, input_archivo_label, input_archivo_boton_eliminar);
        }
    }
}

/**
 * Mostrar los planes de la empresa seleccionada.
 * @returns {void}
 * @author Esperanza Olivo
 */
function mostrarPlanes() {
    let empresa_id = empresa_seleccionada.id;
    let buscar = $('#buscador-plan').val();
    let filtro_tipo_prueba_id = $('#filtro_tipo_prueba_id').val();
    if ($.fn.DataTable.isDataTable('#tabla-planes')) {
        tabla_planes.destroy();
    }
    $('#buscador-plan').remove();
    $('#tbody-planes').empty();
    let planes = empresa_seleccionada.planes;
    if (planes.length > 0) {
        for (let i = 0; i < planes.length; i++) {
            if (!planes[i].plan || !planes[i].plan.tipo_prueba_id) {
                continue;
            }
            if (
                (filtro_tipo_prueba_id == 'Todos') ||
                (filtro_tipo_prueba_id == '1' && planes[i].plan.tipo_prueba_id == 1) ||
                (filtro_tipo_prueba_id == '2' && planes[i].plan.tipo_prueba_id == 2) ||
                (filtro_tipo_prueba_id == '3' && planes[i].plan.tipo_prueba_id != 3)
            ) {
                let estado = obtenerEstadoPlan(
                    planes[i].estado.id,
                    planes[i].estado.nombre,
                    planes[i].por_facturar,
                    planes[i].renovando,
                    null,
                    planes[i].plan_proximo_id
                );

                let acciones = obtenerAcciones(
                    planes[i].estado.id,
                    planes[i].id, empresa_id,
                    planes[i].plan.tipo_prueba_id,
                    planes[i].plan.nombre,
                    planes[i]?.archivos[0]?.id ?? '0',
                    empresa_seleccionada.nombre_comercial
                );

                let modificado = '';
                if (planes[i].plan_original == 0) {
                    modificado = `<i class="bi bi-wrench me-3 text-blue-40" ${crearTooltip({placement: 'top', content: 'Plan modificado', toggle: 'popover' })}></i>`;
                }
                let fecha_vencimiento = '';
                if (planes[i].fecha_vencimiento != null) {
                    fecha_vencimiento = `<span class="ms-3">Vencimiento: ${obtenerFecha(planes[i].fecha_vencimiento)}</span>`;
                }
                let fecha_creacion = '';
                if (planes[i].created_at != null) {
                    fecha_creacion = `Creación: ${obtenerFecha(planes[i].created_at)}`;
                }
                let fecha_inicio = '';
                if (planes[i].fecha_inicio != null) {
                    fecha_inicio = `Activación: ${obtenerFecha(planes[i].fecha_inicio)}`;
                }
                let pruebas_plan = '';
                if (planes[i].pruebas !== undefined) {
                    let pruebas = planes[i].pruebas;
                    for (let j = 0; j < pruebas.length; j++) {
                        pruebas_plan += `
                            <div
                                class="col-auto me-3 circulo-prueba"
                                style="background-image: url(../imagenes/logos/pruebas/${slugify(planes[i].pruebas[j].nombre)}.png)"
                                ${crearTooltip({placement: 'top', content: planes[i].pruebas[j].nombre, toggle: 'popover' })}
                            ></div>
                        `;
                    }
                }
                let icono = '';
                let title = '';
                if (planes[i].plan.tipo_prueba_id == 1) {
                    title = 'Selección';
                    icono = 'bi-person-fill';
                } else if (planes[i].plan.tipo_prueba_id == 2) {
                    title = 'Organizacional';
                    icono = 'bi-people-fill';
                } else if (planes[i].plan.tipo_prueba_id == 3) {
                    title = 'Vocacional';
                    icono = 'bi-mortarboard-fill';
                }
                let opcion_editar = `
                    <button type="button" class="btn btn-text-primary-border text-white btn-circle no-visited" ${crearTooltip({placement: 'top', content: 'Editar', toggle: 'popover' })} onclick="window.location.href='/empresas-planes/${planes[i].id}/edit'">
                        <i class="bi bi-pencil-fill"></i>
                    </button>
                `;
                if (planes[i]?.plan_proximo_id) {
                    opcion_editar = `
                        <button type="button" class="btn btn-text-primary-border text-white btn-circle no-visited dropdown" ${crearTooltip({placement: 'top', content: 'Editar', toggle: 'popover' })}>
                            <i class="bi bi-pencil-fill" data-bs-toggle="dropdown" data-bs-auto-close="outside" aria-expanded="false"></i>
                            <div class="dropdown-menu">
                                <a href="/empresas-planes/${planes[i].id}/edit" class="dropdown-item no-visited pointer py-2">Editar plan vigente</a>
                                <a href="/empresas-planes/${planes[i]?.plan_proximo_id}/edit" class="dropdown-item no-visited pointer py-2">Editar plan próximo</a>
                            </div>
                        </button>
                    `;
                }
                $('#tbody-planes').append(`
                    <tr>
                        <td style="border-bottom: 0px!important;">
                            <div class="border border-1 rounded rounded-3 text-gray-30">
                                <div class="row m-0 w-100 px-3 pt-6 text-headline-6">
                                    <div class="col">
                                        <div class="row align-items-center">
                                            <div class="col-auto mb-0">
                                                <p class="text-gray-30 text-headline-4 mb-0" ${crearTooltip({placement: 'top', content: `Plan ${title === "Selección" ? "de " : ""}${title.toLowerCase()}`, toggle: 'popover' })}>
                                                    <i class="bi ${icono} me-3"></i> ${modificado} ${planes[i].plan.nombre}
                                                </p>
                                            </div>
                                            <div class="col-auto">
                                                ${estado}
                                            </div>
                                            <div class="col-auto">
                                                <p class="text-headline-5 text-gray-30 d-flex align-items-center mb-0">
                                                    <i class="bi bi-person-fill"></i>&nbsp;<span class="text-label-2">${planes[i].cantidad_usuarios}&nbsp;${fecha_vencimiento}</span>
                                                </p>
                                            </div>
                                            <div class="col-12 mt-3">
                                                <div class="row w-100 m-0">${pruebas_plan}</div>
                                            </div>
                                            <div class="col-12 mt-3">

                                            </div>
                                        </div>
                                    </div>
                                    <div class="col-auto w-120px pt-4 position-relative d-flex justify-content-end">
                                        ${opcion_editar}
                                        ${crearBoton({
                                            clases: 'btn btn-text-primary-border text-white btn-circle ms-3',
                                            texto: '<i class="bi bi-three-dots-vertical"></i>',
                                            adicional: 'data-bs-toggle="dropdown" aria-expanded="false"'
                                        })}
                                        ${acciones}
                                    </div>
                                </div>
                                <div class="d-flex justify-content-between w-100 mx-0 mb-6 px-3">
                                    <div class="d-flex align-items-center ps-3 column-gap-3">
                                        <div>
                                            ${crearTag({
                                                class: 'tag-sm tag-tonal-yellow',
                                                texto: `<i class="bi bi-briefcase"></i> Vacantes ${planes[i].cantidad_ofertas_laborales !== null ? planes[i].cantidad_ofertas_laborales : ''}`
                                            })}
                                        </div>
                                        <div>
                                            ${crearTag({
                                                class: 'tag-sm tag-tonal-yellow',
                                                texto: `<i class="bi bi-box"></i> Unidades: ${planes[i].unidades !== null ? planes[i].unidades : ''}`
                                            })}
                                        </div>
                                        <div>
                                            ${crearTag({
                                                class: 'tag-sm tag-tonal-yellow',
                                                texto: `<i class="bi bi-clock"></i>  Tiempo: ${planes[i].vigencia_dias !== null ? planes[i].vigencia_dias : ''} días`
                                            })}
                                        </div>
                                    </div>
                                    <div class="d-flex justify-content-end align-items-end pe-3">
                                        <p class="text-label-2 mb-0">
                                            <span class="text-gray-50 me-3">${fecha_creacion}</span>
                                            <span class="text-gray-30">${fecha_inicio}</span>
                                        </p>
                                    </div>
                                </div>
                            </div>
                        </td>
                    </tr>
                `);
            }
        }

        // Mostrar cards de planes de créditos
        let planes_creditos_mostrados = [];
        for (let i = 0; i < planes.length; i++) {
            if (planes[i].plan_credito && planes[i].plan_credito.id) {
                // Evitar duplicados de plan_credito
                if (!planes_creditos_mostrados.includes(planes[i].plan_credito.id)) {
                    planes_creditos_mostrados.push(planes[i].plan_credito.id);

                    let plan_credito = planes[i].plan_credito;
                    let creditos_totales = planes[i].creditos !== null ? planes[i].creditos : 0;
                    let creditos_restantes = planes[i].creditos_restantes !== null ? planes[i].creditos_restantes : 0;
                    let creditos_promedio = empresa_seleccionada.creditos_promedio_accion || 0;
                    let acciones_estimadas = creditos_restantes > 0 && creditos_promedio > 0
                        ? Math.floor(creditos_restantes / creditos_promedio)
                        : 0;

                    let estado_credito = creditos_restantes > 0
                        ? `<span class="tag tag-sm tag-tonal-green text-label-1">Disponible</span>`
                        : `<span class="tag tag-sm tag-tonal-red text-label-1">Agotado</span>`;

                    let indicador_proximo_credito = '';
                    if (planes[i]?.plan_proximo_id) {
                        indicador_proximo_credito = `<span class="tag tag-sm tag-tonal-purple ms-2">Próximo disponible</span>`;
                    }

                    let precio_informacion= '';
                    if (plan_credito.precio) {
