function obtenerFecha(fecha) {
    let fecha_obj = new Date(fecha);
    let dia = ('0' + fecha_obj.getUTCDate()).slice(-2);
    let mes = ('0' + (fecha_obj.getUTCMonth() + 1)).slice(-2);
    let año = fecha_obj.getUTCFullYear();
    return `${dia}/${mes}/${año}`;
}

/**
 * Obtener el estado del plan.
 * @param {int} estado_id Id del estado del plan.
 * @param {string} nombre Nombre del estado del plan.
 * @param {bool} por_facturar Indica si el plan está por facturar.
 * @param {bool} renovando Indica si el plan está en proceso de renovación.
 * @param {int} empresa_plan_id Id del plan de la empresa, necesario para mostrar el detalle del plan al hacer click en el estado.
 * @param {bool} proximo Indica si el plan es próximo a vencer, para mostrar un badge de "Próximo" en el estado del plan.
 * @returns {string} 
 * @author Esperanza Olivo
 */
function obtenerEstadoPlan(estado_id, nombre, por_facturar = 0, renovando = 0, empresa_plan_id = null, proximo = false) {
    let detalle_empresa_plan = '';
    if (empresa_plan_id != null) {
        detalle_empresa_plan = `onclick="abrirDetallePlan(${empresa_plan_id})"`;
    }
    let badge_proximo = '';
    if (proximo) {
        badge_proximo = `<span class="position-absolute badge badge-proximo bg-purple rounded-pill text-label-2 py-0 px-1 fw-normal"><div class="text-white texto-proximo">Próximo: </div>+1</span>`;
    }
    let estado = '';
    if (por_facturar == 1) {
        estado = `<span class="alert badge-estado-plan badge-estado-por-facturar estado-por-facturar text-label-1 px-0 py-1 mb-0 fw-bold pointer" ${detalle_empresa_plan}>Por facturar${badge_proximo}</span>`;
    } else if (renovando == 1) {
        estado = `<span class="alert badge-estado-plan badge-estado-renovado estado-renovado text-label-1 px-0 py-1 mb-0 fw-bold pointer" ${detalle_empresa_plan}>Renovando${badge_proximo}</span>`;
    } else if (estado_id == 1) {
        estado = `<span class="alert badge-estado-plan badge-estado-activo estado-activo text-label-1 px-0 py-1 mb-0 fw-bold pointer" ${detalle_empresa_plan}>${nombre}${badge_proximo}</span>`;
    } else if (estado_id == 2) {
        estado = `<span class="alert badge-estado-plan badge-estado-inactivo estado-inactivo text-label-1 px-0 py-1 mb-0 fw-bold pointer" ${detalle_empresa_plan}>${nombre}${badge_proximo}</span>`;
    } else if (estado_id == 3) {
        estado = `<span class="alert badge-estado-plan badge-estado-proximo estado-proximo text-label-1 px-0 py-1 mb-0 fw-bold pointer" ${detalle_empresa_plan}>${nombre}${badge_proximo}</span>`;
    } else if (estado_id == 4) {
        estado = `<span class="alert badge-estado-plan badge-estado-por-vencer estado-por-vencer text-label-1 px-0 py-1 mb-0 fw-bold pointer" ${detalle_empresa_plan}>${nombre}${badge_proximo}</span>`;
    } else if (estado_id == 5) {
        estado = `<span class="alert badge-estado-plan badge-estado-vencido estado-vencido text-label-1 px-0 py-1 mb-0 fw-bold pointer" ${detalle_empresa_plan}>${nombre}${badge_proximo}</span>`;
    }

    return estado;
}

/**
 * Obtener las acciones para la tabla de recompras.
 *
 * @param {number} estado_id Id del estado
 * @param {number} id Id del plan
 * @param {number} empresa_id Id de la empresa
 * @param {number} tipo_prueba_id Id del tipo de prueba
 * @param {string} tipo_prueba_nombre Nombre del tipo de prueba
 * @param {number} id_archivo Id del archivo
 * @param {string} nombre_comercial_empresa Nombre comercial de la empresa
 * @returns {string}
 * @author José Manuel Jimenez
 * @author Fahibram Cárcamo
 * @author Daniel Beltrán
 */
function obtenerAcciones(estado_id, id, empresa_id, tipo_prueba_id, tipo_prueba_nombre, id_archivo, nombre_comercial_empresa) {
    let acciones_html = '<ul class="dropdown-menu py-1">';

    if ([1, 4, 5].includes(estado_id)) {
        acciones_html += `<li class="py-1">
            <button class="dropdown-item text-body-2 text-gray-30" type="button" onclick="generarEnlaceCreacion(${id})">Renovar</button>
        </li>`;
    }

    acciones_html += `
        <li class="py-1">
            <button type="button" class="dropdown-item text-body-2 text-gray-30" onclick="window.location = '/facturar-plan/${id}'">Facturación de recompra</button>
        </li>
        <li class="py-1">
            <button
                type="button"
                class="dropdown-item text-body-2 text-gray-30"
                onclick="abrirHistorialRecompras(${empresa_id}, ${tipo_prueba_id}, '${tipo_prueba_nombre}', '${nombre_comercial_empresa}')"
            >
                Historial de recompras
            </button>
        </li>
        <li class="py-1">
            <button type="button" class="dropdown-item text-body-2 text-gray-30" onclick="abrirFacturaPlan(${id_archivo})">Ver factura</button>
        </li>
    `;

    if ([1, 3].includes(estado_id)) {
        acciones_html += `<li class="py-1"><button class="dropdown-item text-body-2 text-danger" type="button" onclick="abrirModalConfirmarEliminarPlan(${id})">Eliminar</button></li>`;
    }

    acciones_html += '</ul>';

    return acciones_html;
}

/**
 * Generar acciones para planes de creditos.
 *
 * @param {number} estado_id ID del estado del plan.
 * @param {number} id ID del plan de empresa.
 * @param {number} empresa_id ID de la empresa.
 * @param {number} archivo_id ID del archivo.
 * @param {string} nombre_comercial_empresa Nombre comercial de la empresa.
 * @returns {string}
 * @author Jose Manuel Jimenez
 * @author Fahibram Carcamo
 * @author Sergio Vargas
 * @author Daniel Beltrán
 */
function obtenerAccionesCreditos(estado_id, id, empresa_id, archivo_id, nombre_comercial_empresa, nombre_plan, creditos, creditos_restantes) {
    let acciones_html = '<ul class="dropdown-menu py-1">';

    if ([1, 4, 5].includes(estado_id)) {
        acciones_html += `<li class="py-1">
            <button class="dropdown-item text-body-2 text-gray-30" type="button" onclick="generarEnlaceCreacion(${id})">Renovar</button>
        </li>`;
    }

    acciones_html += `
        <li class="py-1">
            <button
                type="button"
                class="dropdown-item text-body-2 text-gray-30"
                onclick="abrirHistorialRecomprasCreditos(${empresa_id}, '${nombre_comercial_empresa}')"
            >
                Historial de recompras
            </button>
        </li>
        <li class="py-1">
            <button type="button" class="dropdown-item text-body-2 text-gray-30" onclick="abrirFacturaPlan(${archivo_id})">Ver factura</button>
        </li>
        <li class="py-1">
            <button type="button" class="dropdown-item text-body-2 text-gray-30" onclick="abrirDetallePlanCreditos(${empresa_id}, '${nombre_plan}', ${creditos})">Ver consumo</button>
        </li>
    `;

    if ([1, 2, 3].includes(estado_id)) {
        acciones_html += `<li class="py-1"><button class="dropdown-item text-body-2 text-gray-30" type="button" onclick="inactivar(${id})">Inactivar</button></li>`;
    }

    if ([1, 3].includes(estado_id) && creditos_restantes != null && creditos_restantes == creditos) {
        acciones_html += `<li class="py-1"><button class="dropdown-item text-body-2 text-danger" type="button" onclick="abrirModalConfirmarEliminarPlan(${id})">Eliminar</button></li>`;
    }

    acciones_html += '</ul>';

    return acciones_html;
}

/**
 * Abrir el modal para confirmar la eliminación de un plan asignado.
 *
 * @param {number} empresa_plan_id ID del plan de empresa.
 * @returns {void}
 * @author Daniel Beltrán
 */
function abrirModalConfirmarEliminarPlan(empresa_plan_id) {
    empresa_plan_id_eliminar = empresa_plan_id;
    $('#nombre-confirmar-eliminacion').text('Se eliminará el plan seleccionado');
    $('#modal-confirmar-eliminacion').find('.btn-danger').attr('onclick', 'eliminarPlanAsignado(empresa_plan_id_eliminar)');
    $('#modal-confirmar-eliminacion').modal('show');
}

/**
 * Eliminar un plan asignado a una empresa.
 *
 * @param {number} empresa_plan_id ID del plan de empresa.
 * @returns {void}
 * @author Daniel Beltrán
 */
function eliminarPlanAsignado(empresa_plan_id) {
    $.ajax({
        type: 'DELETE',
        url: `/empresas-planes/${empresa_plan_id}`,
        data: {
            _token: $('meta[name="csrf-token"]').attr('content')
        }
    }).done((respuesta) => {
        mostrarToast('success', respuesta.mensaje);
        obtenerDatosGestionarEmpresa(empresa_seleccionada.id);
        empresa_plan_id_eliminar = null;
        $('#modal-confirmar-eliminacion').modal('hide');
    }).fail((error) => {
        const mensaje_error = error.responseJSON?.mensaje || 'Ocurrió un error al eliminar el plan';
        mostrarToast('danger', mensaje_error);
        empresa_plan_id_eliminar = null;
        $('#modal-confirmar-eliminacion').modal('hide');
    });
}

/**
 * Abrir la factura del plan en una nueva pestaña del navegador.
 *
 * @param {number} factura_id Id de la factura.
 * @returns {void}
 * @author Andres Morales
 */
async function abrirFacturaPlan(factura_id) {
    if (!factura_id) {
        mostrarToast('danger', 'No se encontró la factura');
        return;
    }

    try {
        const respuesta = await $.ajax({
            type: 'GET',
            url: `/archivos-abrir/${factura_id}`,
            xhrFields: { responseType: 'blob' }
        });

        const blobUrl = window.URL.createObjectURL(respuesta);
        window.open(blobUrl, '_blank');
    } catch (error) {
        mostrarToast('danger', 'Ocurrió un error al intentar abrir la factura');
    }
}

function abrirAcciones(elemento) {
    $(elemento).parent().find('.acciones-lista').removeClass('d-none');
