                    let fecha_hora_actuales = moment();
                    let fecha_hora_inicio = moment(row.fecha_inicio);
                    let dias_consumidos = fecha_hora_actuales.clone().diff(fecha_hora_inicio.clone(), 'days');

                    if (row.fecha_vencimiento == null) {
                        return `${dias_consumidos}/Ilimitado`;
                    } else {
                        let fecha_hora_vencimiento = moment(row.fecha_vencimiento);
                        if (fecha_hora_actuales.clone().isAfter(fecha_hora_vencimiento.clone(), 'day')) return `${row.vigencia_dias}/${row.vigencia_dias}`;
                        else return dias_consumidos > row.vigencia_dias ? `${row.vigencia_dias}/${row.vigencia_dias}` : `${dias_consumidos}/${row.vigencia_dias}`;
