                    let arreglo_ruta_archivo = archivo_factura.ruta.split('/');
                    let nombre_archivo_factura = arreglo_ruta_archivo[arreglo_ruta_archivo.length - 1];
                    let indice_ultimo_punto = nombre_archivo_factura.lastIndexOf('.');

                    if (indice_ultimo_punto === -1) return '---';

                    let nombre_archivo_factura_sin_extension = nombre_archivo_factura.substring(0, indice_ultimo_punto);
                    let extension_archivo_factura = nombre_archivo_factura.substring(indice_ultimo_punto);
                    let nombre_archivo_factura_truncado = nombre_archivo_factura_sin_extension.substring(0, 6);

                    return `${
