/**
 * Descargar documento de la factura de un plan.
 *
 * @param {number} id Id del archivo de la factura.
 * @returns {Promise<void>}
 * @author Fahibram Cárcamo
 */
function descargarFactura(id) {
    $.ajax({
        type: 'POST',
        url : `/empresas-planes-descargar-factura/${id}`,
        data: { _token: $('meta[name="csrf-token"]').attr('content') },
        xhrFields: {
            responseType: 'blob'
        },
        success: function (respuesta) {
            let url = window.URL.createObjectURL(respuesta);
            let a   = document.createElement('a');
            a.href  = url;

            a.download = `archivo_de_factura_${id}.pdf`;
            document.body.appendChild(a);
            a.click();
            window.URL.revokeObjectURL(url);
            document.body.removeChild(a);
        }
    }).then(() => {
        mostrarToast('success', 'PDF generado correctamente.');
    }).catch((error) => {
        mostrarToast('danger', 'Ocurrió un error al descargar el archivo.');
    });
}

