/**
 * Validar si 2 arrays son iguales
 *
 * @param {array} arr1 primer array a validar.
 * @param {array} arr2 segundo array a validar.
 * @returns {Boolean}
 * @author José Manuel Jiménez
 */
function arraysIguales(arr1, arr2) {
    if (arr1.length !== arr2.length) {
        return false;
    }
    return arr1.every((element, index) => element === arr2[index]);
}

