$('#logo_recorte').on('change', evento => {
    let archivo_logo = evento.target.files[0];
    if (archivo_logo && archivo_logo.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onload = evento => {
            let imagen = new Image();
            imagen.onload = function() {
                if (imagen.height > 500) {
                    validacion_logo_mensaje = 'La imagen es demasiado grande. Intenta con dimensiones inferiores a 500px de alto.';
                    logo_valido = false;
                } else if (archivo_logo.size > 400_000) {
                    validacion_logo_mensaje = 'La imagen es demasiado pesada. Intenta con un peso inferior o igual a 400KB.';
                    logo_valido = false;
                } else if (!['image/png', 'image/jpg', 'image/jpeg'].includes(archivo_logo.type)) {
                    validacion_logo_mensaje = 'El formato no es válido. Carga una imagen en JPG o PNG.';
                    logo_valido = false;
                } else {
                    validacion_logo_mensaje = '';
                    logo_valido = true;
                }
            };
            imagen.src = evento.target.result;
        };
        reader.readAsDataURL(archivo_logo);
    } else {
        alert('Por favor selecciona un archivo de imagen válido.');
    }
});

