/**
 * Función que abre el modal para filtrar las empresas.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function abrirModalFiltrosAvanzadosEmpresas() {
    $('#modal-filtros-avanzados-empresas').modal('show');
}

/**
 * Función busca los planes de un tipo de prueba para el filtrado.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function seleccionarTipoPruebaFiltro(tipo_prueba_id) {
    $('#filtro_plan_id').empty();
    if (tipo_prueba_id == '') {
        $('#filtro_plan_id').append(`<option value="">Todos</option>`);
        $('#filtro-plan').addClass('d-none');
    } else {
        $.ajax({
            type : 'GET',
            url : `/planes-listado`,
            data : {
                tipo_prueba_id: tipo_prueba_id
            },
            success: function(respuesta) {
                let planes = respuesta.data;
                $('#filtro_plan_id').append(`<option value="">Todos</option>`);
                for (let i = 0; i < planes.length; i++) {
                    $('#filtro_plan_id').append(`
                        <option value="${planes[i].id}">${planes[i].nombre}</option>
                    `);
                }
            },
            error: function(error) {
                console.log(error);
            }
        });
        $('#filtro-plan').removeClass('d-none');
    }
}

/**
 * Función recarga las empresas con el filtro aplicado.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function aplicarFiltrosAvanzadosEmpresas() {
    mostrarEmpresas();
    $('#modal-filtros-avanzados-empresas').modal('hide');
}

/**
 * Función que limpia los filtros aplicados en las empresas.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function borrarFiltrosAvanzadosEmpresas() {
    $('#modal-filtros-avanzados-empresas .select2-filtro').val('').trigger('change').trigger('select2:select');
    aplicarFiltrosAvanzadosEmpresas();
}

/**
 * Función que muestra la lista de las empresas.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function mostrarEmpresas() {
    let estado = !archivadas;
    let tipo_prueba_id = $('#filtro_tipo_prueba_id').val();
    let plan_id = $('#filtro_plan_id').val();
    let ejecutivo_id = $('#filtro_ejecutivo_id').val();
    let rango_fechas = $('#filtro_fecha_hora').val();
    if (rango_fechas != '') {
        rango_fechas = rango_fechas.split(" a ");
    }
    let pais_id = $('#pais_id').val();
    let departamento_id = $('#departamento_id').val();
    let estado_plan_id = $('#filtro_estado').val();
    let ciudad_id = $('#ciudad_id').val();
    inicializarTooltips()
    $.ajax({
        type: 'GET',
        url: `/empresas-listado-tabla`,
        data: {
            'solo_principales': true,
            'estado_plan_id': estado_plan_id,
            'activo': estado,
            'tipo_prueba_id': tipo_prueba_id,
            'plan_id': plan_id,
            'ejecutivo_id': ejecutivo_id,
            'rango_fechas': rango_fechas,
            'pais_id': pais_id,
            'departamento_id': departamento_id,
            'ciudad_id': ciudad_id
        },
        success: function(empresas) {
            cantidad_empresas_listado = 0;
            empresas_listado = empresas;
            if ($.fn.DataTable.isDataTable('#tabla-empresas')) {
                tabla_empresas.destroy();
            }
            $('#buscador-empresas').remove();
            $('#tbody-empresas').empty();
            for (let i = 0; i < empresas.length; i++) {
                cantidad_empresas_listado++;
                crearItemTabla(empresas[i]);
                let sucursales = empresas[i].sucursales;
                for (let j = 0; j < sucursales.length; j++) {
                    cantidad_empresas_listado++;
                    crearItemTabla(sucursales[j], 'sucursal', empresas[i].plan_seleccion, empresas[i].plan_organizacional, empresas[i].plan_vocacional);
                }
            }
            tabla_empresas = $('#tabla-empresas').DataTable({
                language: lenguajeDatatables,
                deferRender: true,
                lengthMenu: [
                    [ 10, 25, 50, 100, 200],
                    [ 10, 25, 50, 100, 200]
                ],
                columnDefs: [
                    { targets: [0, 1], orderable: false }
                ],
            });
            mostrarComponenteNumeroRegistrosTabla('tabla-empresas');
            $('colgroup').addClass('d-none');
            mostrarOcultarColumnas();
            tabla_empresas.on('page order length', function () {
                setTimeout(function() {
                    mostrarOcultarColumnas();
                }, 30);
            });
            $(`#buscador-tabla-empresas`).empty();
            $(`#buscador-tabla-empresas`).append(`
                <div class="input-container input-icon mb-3" id="contenedor-buscador-tabla-empresas">
                    <i class="bi bi-search"></i>
                    <i class="bi bi-filter pointer" style="right: 10px!important; left: auto!important;" onclick="abrirModalFiltrosAvanzadosEmpresas();"></i>
                </div>
            `);
            var buscador_datatables = $(`#tabla-empresas_wrapper .dt-search .dt-input`).first();
            $(buscador_datatables).addClass('rounded-2 text-body-2 input-filtro');
            $(buscador_datatables).prop('placeholder', 'Buscar');
            $(`#contenedor-buscador-tabla-empresas`).append(buscador_datatables);
            $(`#tabla-empresas_wrapper .dt-layout-cell.dt-end `).first().addClass('d-none');
        },
        error: function(error) {
            console.log(error);
        }
    });
}

/**
 * Función que muestra cada item de empresa o sucursal.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function crearItemTabla(item, tipo = 'empresa', plan_seleccion = null, plan_organizacional = null, plan_vocacional = null) {
    let campo_sucursal = '';
    if (tipo == 'empresa' && item.sucursales.length > 0) {
        campo_sucursal = `
            <div class="width-60px rounded-1 badge-estado-plan badge-estado-inactivo nowrap pointer" onclick="mostrarOcultarSucursales(this, ${item.id})">
                ${item.sucursales_count} <i class="bi bi-caret-down-fill"></i>
            </div>
        `;
    }
    let planes = '';
    let clase = '';
    let bg = '';
    if (tipo == 'sucursal') {
        clase = `empresa-${item.empresa_id} d-none`;
        bg = 'bg-gray-90';
        planes = `
            <td class="${bg}">
                ${obtenerEstadoPlan(
                    plan_seleccion?.estado?.id ?? null,
                    plan_seleccion?.estado?.nombre ?? null,
                    plan_seleccion?.por_facturar ?? null,
                    plan_seleccion?.renovando ?? null,
                    plan_seleccion?.id ?? null,
                    plan_seleccion?.plan_proximo
                )}
            </td>
            <td class="${bg}">
                ${obtenerEstadoPlan(
                    plan_organizacional?.estado?.id ?? null,
                    plan_organizacional?.estado?.nombre ?? null,
                    plan_organizacional?.por_facturar ?? null,
                    plan_organizacional?.renovando ?? null,
                    plan_organizacional?.id ?? null,
                    plan_organizacional?.plan_proximo
                )}
            </td>
            <td class="${bg}">
                ${obtenerEstadoPlan(
                    plan_vocacional?.estado?.id ?? null,
                    plan_vocacional?.estado?.nombre ?? null,
                    plan_vocacional?.por_facturar ?? null,
                    plan_vocacional?.renovando ?? null,
                    plan_vocacional?.id ?? null,
                    plan_vocacional?.plan_proximo
                )}
            </td>
        `;
    } else {
        planes = `
            <td class="${bg}">
                ${obtenerEstadoPlan(
                    item?.plan_procesos_de_seleccion?.estado?.id ?? null,
                    item?.plan_procesos_de_seleccion?.estado?.nombre ?? null,
                    item?.plan_procesos_de_seleccion?.por_facturar ?? null,
