            <td class="${bg} d-none columna-tamano-empresa">${item?.tamano_empresa?.nombre ?? ''}</td>
            <td class="${bg} d-none columna-sector">${item?.sector?.nombre ?? ''}</td>
            <td class="${bg} d-none columna-direccion">${item?.direccion ?? ''}</td>
            <td class="${bg} d-none columna-representante">${item?.nombre_representante ?? ''}</td>
