                <div class="col-auto px-0 dropdown">
                    <i class="bi bi-three-dots dropdown-toggle text-blue-40 pointer" data-bs-toggle="dropdown" data-bs-auto-close="outside" aria-expanded="false"></i>
                    <div class="dropdown-menu">
                        <a href="/empresas-gestionar/${item.id}" class="dropdown-item no-visited pointer py-2">Gestionar empresa</a>
                        <div class="dropdown-item no-visited pointer py-2" onclick="abrirHistorialCambios(${item?.id}, '${item?.razon_social}', '${item?.creado_administrador}')">Historial de cambios</div>
