}

/**
 * Función que muestra u oculta las sucursales de una empresa.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function mostrarOcultarSucursales(elemento, empresa_id_padre) {
    if ($(elemento).find('.bi-caret-down-fill').first().length > 0) {
        $('.empresa-' + empresa_id_padre).removeClass('d-none');
        $(elemento).find('.bi-caret-down-fill').first().removeClass('bi-caret-down-fill').addClass('bi-caret-up-fill');
    } else {
        $('.empresa-' + empresa_id_padre).addClass('d-none');
        $(elemento).find('.bi-caret-up-fill').first().removeClass('bi-caret-up-fill').addClass('bi-caret-down-fill');
    }
}

/**
 * Función que evalua que columnasn adicionales hay que mostrar.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function mostrarOcultarColumnas() {
    let columnas = $('.filtro-columna');
    for (let i = 0; i < columnas.length; i++) {
        let valor = $(columnas[i]).val();
        let checked = $(columnas[i]).prop('checked');
        if (checked) {
            $('.' + valor).removeClass('d-none');
        } else {
            $('.' + valor).addClass('d-none');
        }
    }
}

/**
 * Función que abre el modal para confirmar la eliminación de empresas.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function abrirModalConfirmarEliminarEmpresas(empresa_id = null, nombre_empresa = '') {
    empresa_id_eliminar = empresa_id;
    nombre_empresa = 'Eliminar ' + nombre_empresa;
    $('#nombre-confirmar-eliminacion').text(nombre_empresa);
    $('#modal-confirmar-eliminacion').modal('show');
}

/**
 * Confirmar la eliminación de empresas.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function confirmarEliminarEmpresas() {
    eliminarEmpresas(empresa_id_eliminar);
}

/**
 * Eliminar empresas.
 *
 * @returns {void}
 * @author Daniel Beltrán
 */
async function eliminarEmpresas(empresa_id = null) {
    await $.ajax({
        type: 'DELETE',
        url : `/empresas/${empresa_id}`,
        data: {
            _token: $('meta[name="csrf-token"]').attr('content'),
        }
    }).then((respuesta) => {
        empresa_id_eliminar = null;
        empresa_nombre_eliminar = '';
        if (respuesta.tipo != undefined && respuesta.tipo == 'success') {
            mostrarToast('success', respuesta.mensaje);
            mostrarEmpresas();
        } else if (respuesta.errors != undefined) {
            mostrarToast('danger', respuesta.message);
        }
        $('#modal-confirmar-eliminacion').modal('hide');
    }).catch((error) => {
        mostrarToast('danger', error.responseJSON.errors);
        empresa_id_eliminar = null;
        empresa_nombre_eliminar = '';
        $('#modal-confirmar-eliminacion').modal('hide');
    });
}

