function postSuccess(respuesta) {
    if (respuesta.formulario == 'formulario') {
        if (respuesta.data.empresa_id == null) {
            if (vista == 'crear-editar') {
                mostrarToast('success', `La empresa se ${respuesta.accion_realizada} con éxito`);
                $('#empresa-tab').html(`<i class="bi bi-check"></i>`);
                $('#documentos-tab').prop('disabled', false);
                $('#documentos-tab').click();
            } else if (vista == 'gestionar') {
                mostrarToast('success', `La empresa se ${respuesta.accion_realizada} con éxito`);
            }
        } else {
            if (vista == 'crear-editar') {
                if (opcion_form === 'Editar') {
                    localStorage.setItem('notificacionToast', JSON.stringify({
                        tipo_alerta: 'success',
                        texto_1: `La sucursal se ${respuesta.accion_realizada} con éxito`,
                    }));
                } else {
                    localStorage.setItem('notificacionToast', JSON.stringify({
                        sucursal_creada: true,
                        id_sucursal: respuesta.data.id,
                        nombre_comercial_sucursal: respuesta.data.nombre_comercial
                    }));
                }
                if (tipo_rol_activo_usuario === 'empresa') {
                    window.location.href = '/sucursales';
                } else if (tipo_rol_activo_usuario === 'superadmin') {
                    window.location.href = '/empresas';
                }
            } else if (vista == 'gestionar') {
                mostrarToast('success', `La sucursal se ${respuesta.accion_realizada} con éxito`);
            }
        }
    } else if (respuesta.formulario == 'formulario-archivos') {
        if (Array.isArray(respuesta.data) && respuesta.data.length > 0) actualizarEnlacesPrevisualizacionArchivos(respuesta.data, false);
        mostrarToast('success', `Los documentos se ${respuesta.accion_realizada} con éxito`);
        $('#documentos-tab').html(`<i class="bi bi-check"></i>`);
        $('#contactos-tab').prop('disabled', false);
        $('#contactos-tab').click();
    } else if (respuesta.formulario == 'formulario-contactos') {
        mostrarToast('success', `La información de contacto se ${respuesta.accion_realizada} con éxito`);
        $('#contactos-tab').html(`<i class="bi bi-check"></i>`);
        localStorage.setItem('notificacionToast', JSON.stringify({
            tipo_alerta: 'success',
            texto_1: `La empresa se ${respuesta.accion_realizada} con éxito`,
        }));
        window.location.href='/empresas';
    }
    if (typeof respuesta.data !== 'undefined' && typeof es_sucursal !== 'undefined'){
        if (es_sucursal == false) {
            if (typeof respuesta.data.id !== 'undefined') {
                $('.id').val(respuesta.data.id);
            }
        }
    }
}

/**
 * Validar datos antes de enviar el formulario.
 *
 * @returns {boolean}
 * @author Daniel Beltrán
 * @author Jair Carvajal
 */
function validacionAdicional() {
    if (campo_celular !== null) {
        validacionAdicionalInputTipoCelular(campo_celular, CAMPO_CELULAR_ID);
    }
    if (campo_celular_contacto !== null) {
        validacionAdicionalInputTipoCelular(campo_celular_contacto, CAMPO_CELULAR_CONTACTO_ID);
    }
    if (campo_celular_tesorero !== null) {
        validacionAdicionalInputTipoCelular(campo_celular_tesorero, CAMPO_CELULAR_TESORERO_ID);
    }
    if (campo_celular_usuario !== null) {
        validacionAdicionalInputTipoCelular(campo_celular_usuario, CAMPO_CELULAR_USUARIO_ID);
    }

    if ($('#usuario').length) {
        $('#usuario').val('');
        let usuario_id = $('#usuario_id').val();
        if (usuario_id.length == 0) {
            usuario_id = null;
        }
        let usuario = {
            id                       : usuario_id,
            tipo_documento_id        : $('#tipo_documento_id').val(),
            documento                : $('#documento_usuario').val(),
            nombres                  : $('#nombres').val(),
            apellidos                : $('#apellidos').val(),
            email                    : $('#email').val(),
            codigo_iso2_pais_telefono: $(`#codigo_iso2_pais_${CAMPO_CELULAR_USUARIO_ID}`).val(),
            indicativo_telefono      : $(`#indicativo_${CAMPO_CELULAR_USUARIO_ID}`).val(),
            telefono                 : $(`#${CAMPO_CELULAR_USUARIO_ID}`).val()
        };

        $('#usuario').val(JSON.stringify(usuario));
    }

    if (!logo_valido) {
        mostrarToast('danger', validacion_logo_mensaje);
        return false;
    }

    return true;
}

function seleccionarEmpresa(empresa_id) {
    $('.campo-sucursal').addClass('d-none');

    if (empresas_principales.length) {
        let ejecutivo = empresas_principales.filter(empresa_principal => empresa_principal.id === parseInt(empresa_id))[0].ejecutivo;
        $('#ejecutivo-cuenta').text('Ejecutivo de cuenta: ' + ejecutivo?.nombre_completo);
        let campo_ejecutivo_id = $('input[type="hidden"]#ejecutivo_id');
        if (campo_ejecutivo_id) {
            campo_ejecutivo_id.val(ejecutivo?.id);
        }
    }

    $('#empresa_id').val('');
    if (empresa_id.length > 0) {
        $('#empresa_id').val(empresa_id);
        $('.campo-sucursal').removeClass('d-none');
