/**
 * Obtener los departamentos según el país seleccionado.
 *
 * @returns {void}
 * @author Daniel Beltrán
 */
$(document).on('change', '#pais_id', function() {
    const pais_id = $(this).val();
    $('#departamento_id').empty();
    $('#ciudad_id').empty();
    if (pais_id != null && pais_id != '') {
        $.ajax({
            type: 'GET',
            url : `/departamentos-listado`,
            data: {
                pais_id: pais_id
            }
        }).then((response) => {
            const datos = response.data;
            $('#departamento_id').append(`<option></option>`);
            datos.forEach((item) => {
                $('#departamento_id').append(new Option(item.nombre, item.id));
            });
            if ($(this).data('departamento_id') != '') {
                $('#departamento_id').val($(this).data('departamento_id')).trigger('change');
            }
        }).catch((error) => {
            console.error(error);
        });
    }
});

