/**
 * Archivar o desarchivar empresa.
 *
 * @returns {void}
 * @author Daniel Beltrán
 */
function archivar() {
    const formulario = $('#formulario-archivar');

    formulario.validate({
        ignore: [] // No ignorar campos ocultos
    });

    const datos = new FormData(formulario[0]);
    datos.append('_token', $('meta[name="csrf-token"]').attr('content'));
    datos.append('activo', archivadas);
    datos.delete('id');

    const id = $('#empresa-archivar-id').val();

    if (formulario.valid()) {
        $.ajax({
            type       : 'POST',
            url        : `/empresas-archivar/${id}`,
            data       : datos,
            processData: false,
            contentType: false
        }).then((respuesta) => {
            mostrarToast('success', respuesta.mensaje);
            $('#modal-archivar').modal('hide');
            formulario[0].reset();
            mostrarEmpresas();
        }).catch((error) => {
            console.error(error);
        });
    }
};

