/**
 * Generar enlace de creación o actualización.
 *
 * @param {number} id ID de la empresa.
 * @returns {void}
 * @author Daniel Beltrán
 */
async function generarEnlaceCreacion(id = null) {
    enlace_creacion = null;
    const URL       = ![undefined, null, ''].includes(id) ? `/generar-enlace-creacion/${id}` : `/generar-enlace-creacion`;

    await $.ajax({
        type: 'POST',
        url : URL,
        data: {
            _token: $('meta[name="csrf-token"]').attr('content')
        }
    }).then((respuesta) => {
        enlace_creacion = respuesta.data;
        $('#enlace-creacion').text(enlace_creacion);
        $('#modal-generar-enlace').modal('show');
    }).catch((error) => {
        console.error(error);
    });
}

/**
 * Copiar enlace de creación.
 *
 * @param {boolean} cerrar_modal Indica si se debe cerrar el modal.
 * @returns {void}
 * @author Daniel Beltrán
 */
function copiarEnlace(cerrar_modal = false) {
    navigator.clipboard.writeText(enlace_creacion);

    if (cerrar_modal) {
        $('#modal-generar-enlace').modal('hide');
    }
}

