/**
 * Actualizar los elementos anchor de previsualización de archivos de la empresa.
 *
 * @param {array} archivos_empresa Arreglo de archivos de la empresa.
 * @param {boolean} reiniciar_campo_archivo Si se debe reiniciar el campo de archivo.
 * @returns {void}
 * @author Fahibram Cárcamo
 * @author Andres Gonzalez
 */
function actualizarEnlacesPrevisualizacionArchivos(archivos_empresa, reiniciar_campo_archivo = true) {
    // Oculta todos los elementos anchor de previsualización de archivos.
    $('.previsualizacion-archivo').addClass('d-none');

    // Muestra los elementos de previsualización de archivos que corresponden con los archivos
    // relacionados con la empresa.
    for (let i = 0; i < archivos_empresa.length; i++) {
        $('#archivo_' + archivos_empresa[i].nombre).prop('href', `/archivos-abrir/${archivos_empresa[i].id}`);
        $('#archivo_' + archivos_empresa[i].nombre).removeClass('d-none');

        let input_archivo = $('#' + archivos_empresa[i].nombre + '.input-file.input-form');
        let input_archivo_label = $('label[for="' + archivos_empresa[i].nombre + '"].nombre-archivo');
        let input_archivo_boton_eliminar = $('#boton-eliminar-archivo-' + archivos_empresa[i].nombre + '.eliminar-archivo');

        if(reiniciar_campo_archivo) {
            reiniciarCampoArchivo(input_archivo, input_archivo_label, input_archivo_boton_eliminar);
        }
    }
}

