                    let fecha_hora_inicio = moment(row.fecha_inicio);
                    let dias_consumidos = fecha_hora_actuales.clone().diff(fecha_hora_inicio.clone(), 'days');

                    if (row.fecha_vencimiento == null) {
                        return `${dias_consumidos}/Ilimitado`;
                    } else {
                        let fecha_hora_vencimiento = moment(row.fecha_vencimiento);
                        if (fecha_hora_actuales.clone().isAfter(fecha_hora_vencimiento.clone(), 'day')) return `${row.vigencia_dias}/${row.vigencia_dias}`;
                        else return dias_consumidos > row.vigencia_dias ? `${row.vigencia_dias}/${row.vigencia_dias}` : `${dias_consumidos}/${row.vigencia_dias}`;
                    }
                }
            },
            {
                title: '<span class="text-body-3">Adjunto</span>',
                data: null,
                className: 'text-body-3 text-center',
                orderable: false,
                searchable: false,
                render: function (data) {
                    let archivo_factura = data.archivos !== undefined && data.archivos !== null && data.archivos.length ? data.archivos[0] : null;

                    if (archivo_factura === null) return '---';

                    let arreglo_ruta_archivo = archivo_factura.ruta.split('/');
                    let nombre_archivo_factura = arreglo_ruta_archivo[arreglo_ruta_archivo.length - 1];
                    let indice_ultimo_punto = nombre_archivo_factura.lastIndexOf('.');

                    if (indice_ultimo_punto === -1) return '---';

                    let nombre_archivo_factura_sin_extension = nombre_archivo_factura.substring(0, indice_ultimo_punto);
                    let extension_archivo_factura = nombre_archivo_factura.substring(indice_ultimo_punto);
                    let nombre_archivo_factura_truncado = nombre_archivo_factura_sin_extension.substring(0, 6);

                    return `${
                        crearBoton({
                            clases: 'btn-text-primary text-decoration-underline',
                            onclick: `descargarFactura(${archivo_factura.id})`,
                            texto: `${nombre_archivo_factura_truncado}...${extension_archivo_factura}`,
                            tooltip: `${crearTooltip({placement: `bottom`,content: `${nombre_archivo_factura}`, toggle: 'popover' })}`
                        })
                    }`;
                }
            },
            {
                title: '<span class="text-body-3">Acciones</span>',
                data: null,
                className: 'text-body-3 text-center',
                orderable: false,
                searchable: false,
                render: function (data, type, row) {
                    return `${
                        crearBoton({
                            clases: 'btn-text-primary btn-circle',
                            texto: '<i class="bi bi-eye"></i>',
                            onclick: `abrirModalConsumosRecompra(${row.id}, '${row.plan.nombre}', '${nombre_comercial_empresa}')`,
                            tooltip: `${crearTooltip({placement: `bottom`,content: 'Ver consumo', toggle: 'popover' })}`
                        })
                    }`;
                }
            }
        ],
        drawCallback: function(settings) {
            inicializarTooltips();
        },
    });

    $('#boton-descargar-historial-recompras').off('click');
    $('#boton-descargar-historial-recompras').on(
