usuario_id_eliminar = null;
usuario_nombre_eliminar = '';

/**
 * Función que abre el modal para confirmar la eliminación de usuarios.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Andres Gonzalez
 */
function abrirModalConfirmarEliminarUsuarios(usuario_id = null, nombre_usuario = '') {
    usuario_id_eliminar = usuario_id;
    let detener_proceso = true;

    for (let elemento of usuarios_seleccionados) {
        let bandera_usuario = $(`#usuario_id_${elemento}`).val();
        if (bandera_usuario === 'false' || bandera_usuario === false) {
            detener_proceso = false;
            break;
        }
    }

    if (detener_proceso) {
        usuario_nombre_eliminar = nombre_usuario;
        if (nombre_usuario == '') {
            nombre_usuario = 'Se van a eliminar ' + usuarios_seleccionados.length + ' usuario(s)';
        } else {
            nombre_usuario = 'Se eliminará el usuario ' + nombre_usuario;
        }
        $('#nombre-confirmar-eliminacion').text(nombre_usuario);
        $('#modal-confirmar-eliminacion').modal('show');
    }else{
        mostrarToast('danger', 'No es posible eliminar el usuario o los usuarios seleccionados porque tienen relaciones con otros módulos.');
    }

}

/**
 * Confirmar la eliminación de usuarios.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 */
function confirmarEliminarUsuarios() {
    eliminarUsuarios(usuario_id_eliminar);
}

/**
 * Eliminar usuarios.
 *
 * @returns {void}
 * @author Daniel Beltrán
 */
async function eliminarUsuarios(usuario_id = null) {
    usuarios_enviar = [];
    if (usuario_id != null) {
        usuarios_enviar.push(usuario_id);
    } else {
        usuarios_enviar = usuarios_seleccionados;
    }
    await $.ajax({
        type: 'POST',
        url : `/usuarios-eliminar-multiples`,
        data: {
            _token: $('meta[name="csrf-token"]').attr('content'),
            ids   : usuarios_enviar
        }
    }).then((respuesta) => {
        if (respuesta.message == 'Usuarios eliminados correctamente' && usuarios_enviar.length == 1 && respuesta.data == 0) {
            mostrarToast('success', `Usuario eliminado correctamente`);
        } else if (respuesta.message == 'Usuarios eliminados correctamente' && respuesta.data == 0) {
            mostrarToast('success', `Usuarios eliminados correctamente`);
        } else {
            mostrarToast('neutral', `Algunos usuarios no fueron eliminados, puede que tengan auditorías.`);
        }
        usuarios_seleccionados = usuarios_seleccionados.filter(usuario => !usuarios_enviar.includes(usuario));
        usuario_id_eliminar = null;
        usuario_nombre_eliminar = '';
        $('#modal-confirmar-eliminacion').modal('hide');
        actualizarDataUsuarios();
        $(".acciones-lista").addClass('d-none');
    }).catch((error) => {
        mostrarToast('danger', error.message);
    });
}

