/**
 * Obtener historial de cambios de un usuario.
 *
 * @param {number} id ID del usuario.
 * @returns {Promise<Array>}
 * @author Daniel Beltrán
 */
async function getHistorialCambiosUsuario(id) {
    let datos = [];
    await $.ajax({
        type: 'GET',
        url : `/usuarios-historial-cambios/${id}`,
        data: {
            event: $('#filtro_tipo_accion').val(),
            created_at: $('#filtro_fecha_hora').val()
        }
    }).then((respuesta) => {
        datos = respuesta.data || [];
    }).catch((error) => {
        console.error(error);
    });
    return datos;
}

/**
 * Validar si 2 arrays son iguales
 *
 * @param {array} arr1 primer array a validar.
 * @param {array} arr2 segundo array a validar.
 * @returns {Boolean}
 * @author José Manuel Jiménez
 */
function arraysIguales(arr1, arr2) {
    if (arr1.length !== arr2.length) {
        return false;
    }
    return arr1.every((element, index) => element === arr2[index]);
}

/**
 * Mostrar la información de la configuración
 *
 * @author José Manuel Jiménez
 */
let actualizar_configuracion = false;
function mostrarConfiguraciones() {
    actualizar_configuracion = false;
    $('#configuracion-1').multiselect('destroy');
    $('#configuracion-2').multiselect('destroy');
    for (let i = 0; i < usuarios.length; i++) {
        if (usuarios[i].usuario != undefined) {
            $('#configuracion-1').append(`
                <option value="${usuarios[i].usuario.id}">${usuarios[i].usuario.nombres} ${usuarios[i].usuario.apellidos}</option>
            `);
            $('#configuracion-2').append(`
                <option value="${usuarios[i].usuario.id}">${usuarios[i].usuario.nombres} ${usuarios[i].usuario.apellidos}</option>
            `);
        }
    }
    $('.switch-config').prop('checked', true);
    for (let i = 0; i < configuraciones_defecto.length; i++) {
        if (configuraciones_defecto[i].id == 1) {
            if (configuraciones_defecto[i].valor == 'todos' || configuraciones_defecto[i].valor == 'administradores') {
                $('#configuracion-1').val([]);
