            } else {
                $('#configuracion-1').val(JSON.parse(configuraciones_defecto[i].valor));
                $('#elegir_usuarios').val('Elegir usuarios').trigger('change').trigger('select2:select');
            }
        }
        if (configuraciones_defecto[i].id == 2) {
            if (configuraciones_defecto[i].valor == 'todos' || configuraciones_defecto[i].valor == 'administradores') {
                $('#configuracion-2').val([]);
                $('#elegir_actividad').val(configuraciones_defecto[i].valor).trigger('change').trigger('select2:select');
            } else {
                $('#configuracion-2').val(JSON.parse(configuraciones_defecto[i].valor));
                $('#elegir_actividad').val('Elegir usuarios').trigger('change').trigger('select2:select');
            }
        }
        if ([3, 4, 6, 7].includes(configuraciones_defecto[i].id) && (configuraciones_defecto[i].valor == '0')) {
            $('#configuracion-' + configuraciones_defecto[i].id).prop('checked', false);
        }
        if (configuraciones_defecto[i].id == 5) {
            $('#configuracion-' + configuraciones_defecto[i].id).val(configuraciones_defecto[i].valor).trigger('change').trigger('select2:select');
        }
        if (configuraciones_defecto[i].id == 8) {
            $('#configuracion-' + configuraciones_defecto[i].id).val(configuraciones_defecto[i].valor);
        }
    }
    for (let i = 0; i < configuraciones_personalizadas.length; i++) {
        if (configuraciones_personalizadas[i].configuracion_id == 1) {
            if (configuraciones_personalizadas[i].valor == 'todos' || configuraciones_personalizadas[i].valor == 'administradores') {
                $('#configuracion-1').val([]);
                $('#elegir_usuarios').val(configuraciones_personalizadas[i].valor).trigger('change').trigger('select2:select');
            } else {
                $('#configuracion-1').val(JSON.parse(configuraciones_personalizadas[i].valor));
                $('#elegir_usuarios').val('Elegir usuarios').trigger('change').trigger('select2:select');
            }
        }
        if (configuraciones_personalizadas[i].configuracion_id == 2) {
            if (configuraciones_personalizadas[i].valor == 'todos' || configuraciones_personalizadas[i].valor == 'administradores') {
                $('#configuracion-2').val([]);
                $('#elegir_actividad').val(configuraciones_personalizadas[i].valor).trigger('change').trigger('select2:select');
            } else {
                $('#configuracion-2').val(JSON.parse(configuraciones_personalizadas[i].valor));
                $('#elegir_actividad').val('Elegir usuarios').trigger('change').trigger('select2:select');
            }
        }
        if ([3, 4, 6, 7].includes(configuraciones_personalizadas[i].configuracion_id) && (configuraciones_personalizadas[i].valor == '0')) {
            $('#configuracion-' + configuraciones_personalizadas[i].configuracion_id).prop('checked', false);
        }
        if (configuraciones_personalizadas[i].configuracion_id == 5) {
            $('#configuracion-' + configuraciones_personalizadas[i].configuracion_id).val(configuraciones_personalizadas[i].valor).trigger('change').trigger('select2:select');
        }
