/**
 * Función que se ejecut al al cambiar un switch
 *
 * @param {boolean} opcion dato que indica si esta o no seleccionado el switch.
 * @param {int} configuracion_id id de configuración a actualizar.
 * @author José Manuel Jiménez
 */
function SeleccionarOpcionSwitch(opcion, configuracion_id) {
    let dato = opcion ? 1 : 0;
    actualizarConfiguracion(dato, configuracion_id);
}

/**
 * Función que se ejecuta al seleccionar una opción de los selects de visibilidad
 *
 * @param {boolean} opcion dato que indica el valor seleccionado en el select.
 * @param {int} configuracion_id id de configuración a actualizar.
 * @author José Manuel Jiménez
 */
function SeleccionarOpcionVisibilidad(opcion, configuracion_id) {
    inizializarMultiselect();
    if (opcion == 'Elegir usuarios') {
        $('#contenedor-elegir-usuarios-' + configuracion_id).addClass('col-3');
        $('#contenedor-elegir-usuarios-' + configuracion_id).removeClass('col-6');
        $('#contenedor-usuarios-' + configuracion_id).removeClass('d-none');
    } else {
        $('#contenedor-elegir-usuarios-' + configuracion_id).removeClass('col-3');
        $('#contenedor-elegir-usuarios-' + configuracion_id).addClass('col-6');
        $('#contenedor-usuarios-' + configuracion_id).addClass('d-none');
    }
    if (actualizar_configuracion) {
        $('#configuracion-' + configuracion_id).val([]);
        actualizarConfiguracion(opcion, configuracion_id);
    }
    $('#configuracion-' + configuracion_id).multiselect("refresh");
}

/**
 * Función que se ejecuta al seleccionar alguno o varios usuarios.
 *
 * @param {int} configuracion_id id de configuración a actualizar.
 * @author José Manuel Jiménez
 */
function seleccionarOpcionSelect(configuracion_id) {
    let usuarios_select = $('#configuracion-' + configuracion_id).val();
    actualizarConfiguracion(JSON.stringify(usuarios_select.map(numero => parseInt(numero))), configuracion_id);
}

/**
 * Actualizar la configuración de la empresa.
 *
 * @param {any} valor valor a actualizar en la configuración seleccionada.
 * @param {int} configuracion_id id de configuración a actualizar.
 * @returns {Promise<void>}
 * @author Daniel Beltrán, José Manuel Jiménez
 */
async function actualizarConfiguracion(valor, configuracion_id) {
    if (actualizar_configuracion) {
        if (configuracion_id == 1 || configuracion_id == 2) {
            if (valor != 'todos' && valor != 'administradores') {
                if (valor == '[]') {
                    mostrarToast('neutral', `Selecciona al menos un usuario`);
                    return false;
                } else if (valor == 'Elegir usuarios') {
                    return false;
                }
            }
        }
        await $.ajax({
            type: 'POST',
            url : `/configuraciones-modelos`,
            data: {
                _token          : $('meta[name="csrf-token"]').attr('content'),
                model_type      : 'App\\Models\\Empresas\\Empresa',
                modelo_id       : empresa_seleccionada.id,
                configuracion_id: configuracion_id,
                valor           : valor
            }
        }).then((respuesta) => {
            mostrarToast('success', respuesta.message);
            datos = respuesta.data || [];
        }).catch((error) => {
            console.error(error);
        });
    }
}

