 */
function seleccionarCheckboxEmpresa(check, empresa_id) {
    if (check) {
        empresas_seleccionadas.push(parseInt(empresa_id));
    } else {
        empresas_seleccionadas = empresas_seleccionadas.filter(id => id !== parseInt(empresa_id));
    }
    if (empresas_seleccionadas.length == cantidad_empresas_listado) {
        $('#check-seleccionar-todos-empresas').prop('indeterminate', false);
        $('#check-seleccionar-todos-empresas').prop('checked', true);
        $('#boton-descargar-excel').html(`<img class="me-3" src="/iconos/excel_icon.svg"> Exportar seleccionado`);
    } else if (empresas_seleccionadas.length == 0) {
        $('#check-seleccionar-todos-empresas').prop('indeterminate', false);
        $('#check-seleccionar-todos-empresas').prop('checked', false);
        $('#boton-descargar-excel').html(`<img class="me-3" src="/iconos/excel_icon.svg"> Exportar todo`);
    } else {
        $('#check-seleccionar-todos-empresas').prop('indeterminate', true);
        $('#boton-descargar-excel').html(`<img class="me-3" src="/iconos/excel_icon.svg"> Exportar seleccionado`);
    }
}

/**
 * metodo para seleccionar todas las empresas en los chackbox para descargar.
 *
 * @returns {void}
 * @author José Manuel Jiménez
 * @author Andres Morales
 */
function seleccionarTodasEmpresas(check) {
    empresas_seleccionadas = [];
    if (check) {
        for (let i = 0; i < empresas_listado.length; i++) {
            empresas_seleccionadas.push(empresas_listado[i].id);
            for (let j = 0; j < empresas_listado[i].sucursales.length; j++) {
                empresas_seleccionadas.push(empresas_listado[i].sucursales[j].id);
            }
        }
        $('#boton-descargar-excel').html(`<img class="me-3" src="/iconos/excel_icon.svg"> Exportar seleccionado`);
    } else {
        $('#boton-descargar-excel').html(`<img class="me-3" src="/iconos/excel_icon.svg"> Exportar todo`);
    }
    mostrarEmpresas();
}

