public function planesAntecedentesActivos(int $empresa_id): Collection {
    return $this->modelo::select('id', 'empresa_id', 'plan_id', 'plan_antecedente_id', 'usuario_id', 'estado_id', 'creditos', 'consultas', 'fecha_inicio', 'fecha_vencimiento', 'precio', 'porcentaje_descuento', 'numero_factura', 'comentario', 'renovando', 'created_at')
        ->with([
            'planAntecedente:id,nombre,consultas,precio,porcentaje_descuento,fecha_inicio_promocion,fecha_fin_promocion',
            'estado:id,nombre',
            'usuario:id,nombres,apellidos',
            'archivos' => function ($archivos) {
                $archivos->select('id', 'modelo', 'modelo_id', 'nombre', 'ruta', 'created_at')
                    ->orderBy('created_at', 'DESC');
            }
        ])
        ->withCount('consumosAntecedentes as consultas_consumidas')
        ->where('empresa_id', $empresa_id)
        ->whereNull('plan_id')
        ->whereNotNull('plan_antecedente_id')
        ->orderBy('created_at', 'DESC')
        ->get();
}

