/**
 * Función para crear un componente de tabs
 * 
 * @param {Object} componente Objeto con las propiedades del componente
 * @returns {string} Código HTML del componente
 * @autor José Manuel Jiménez
 * @autor Jair Carvajal
 */
function crearTabsHorizontal(componente) {
    let tabs = componente.tabs;
    let titulos = '';
    let contenidos = '';
    for (let i = 0; i < tabs.length; i++) {
        titulos += `
            <a class="nav-item-horizontal ${tabs[i].clase_header ? tabs[i].clase_header : ''} ${tabs[i].activo ? 'active' : ''}" ${tabs[i].url ? `href="${tabs[i].url}"` : `href="#tab-${tabs[i].id}" data-bs-toggle="tab"`} ${tabs[i].disabled ? 'disabled aria-disabled="true"' : ''} ${tabs[i].id ? `id="${tabs[i].id}"` : ''}>
                <div class="nav-horizontal text-body-2">
                    <div ${tabs[i].tooltip ? `${crearTooltip({placement: `top`, content: tabs[i].tooltip ,toggle: `popover`,})}` : ''} class="d-flex align-items-center">
                        ${tabs[i].icono ? tabs[i].icono : ''}
                        ${tabs[i].titulo ? `<span class="titulo-nav-horizontal ${tabs[i].clases ? tabs[i].clases : ''}">${tabs[i].titulo}</span>` : ''}
                        ${tabs[i].badget ? `<span class="badge rounded-pill bg-danger ms-3">${tabs[i].badget}</span>` : ''}
                        ${tabs[i].icono2 ? tabs[i].icono2 : ''}
                    </div>
                </div>
            </a>
        `;
        if (tabs[i].contenedor) {
            $(document).ready(function () {
                $(tabs[i].contenedor).append(`
                    <div class="tab-pane fade ${tabs[i].activo ? 'show active' : ''}" id="tab-pasos-${componente.id ? `${componente.id}-` : ''}${tabs[i].id}">
                        ${tabs[i].contenido}
                    </div>
                `);
            });
        } else {
            contenidos += `
                <div class="tab-pane fade ${tabs[i].activo ? 'show active' : ''}" id="tab-${tabs[i].id}">
                    ${tabs[i].contenido}
                </div>
            `;
        }
    }
    return `
        <div class="col-12">
            <div class="nav border-0">
                ${titulos}
            </div>
        </div>
        <div class="col-12">
            <div class="tab-content">
                ${contenidos}

