public function planActivo(int $empresa_id, int $tipo_prueba_id): ?EmpresaPlan {
    return $this->modelo::select('id', 'empresa_id', 'plan_id', 'plan_credito_id', 'usuario_id', 'estado_id', 'unidades', 'cantidad_ofertas_laborales', 'cantidad_usuarios', 'cantidad_pruebas', 'creditos', 'fecha_inicio', 'fecha_vencimiento', 'precio', 'porcentaje_descuento', 'numero_factura', 'comentario', 'plan_original', 'renovando', 'por_facturar', 'created_at')
    ->with([
        'plan:id,tipo_prueba_id,nombre,vigencia,created_at',
        'plan.tipoPrueba:id,nombre',
        'planCredito:id,nombre,creditos,precio,porcentaje_descuento,fecha_inicio_promocion,fecha_fin_promocion',
        'estado:id,nombre',
        'pruebas:id,nombre,slug',
        'usuario:id,nombres,apellidos',
        'archivos' => function ($archivos) {
            $archivos->select('id', 'modelo', 'modelo_id', 'nombre', 'ruta', 'created_at')
            ->orderBy('created_at', 'DESC');
        }
    ])
    ->withCount([
        'consumos as consumos_agendas'           => fn($consumos) => $consumos->whereNotNull('agenda_id'),
        'consumos as consumos_ofertas_laborales' => fn($consumos) => $consumos->whereNotNull('oferta_laboral_id'),
        'consumos as consumos_vacantes'          => fn($consumos) => $consumos->whereNotNull('vacante_id')
    ])
    ->where('empresa_id', $empresa_id)
    ->whereHas('plan', function ($plan) use ($tipo_prueba_id) {
        $plan->where('tipo_prueba_id', $tipo_prueba_id);
    })
    ->whereIn('estado_id', [1, 4])
    ->first();
}

